quests[83827] = { id = 83827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt das Lied zum Schweigen", description = "Die Sirenen... Sie sind hier draußen! Und ich frage mich... haben die Kul Tiraner die Insel nach dem Kristall oder nach diesen Kreaturen benannt?\n\nWas es auch gewesen sein mag, der Ruf dieser Sirenen hat viele unserer Truppen in ihren Untergang geführt.\n\nUnsere Goblinverbündeten haben ein Gerät vorbereitet, um die Kontrolle zu brechen, die sie über unsere Truppen haben.\n\nSchaltet diese \"Sirenen\" aus und verbannt die Bezauberung, die unsere Truppen gefangen hält.", sourceObjective = "Befreit 7 betörte Truppen und tötet Macabea die Meeresbanshee.", progress = "Habt Ihr die Sirenenbedrohung eliminiert?", completion = "Ausgezeichnete Arbeit, {name}. Keine Seele sollte sich solch schrecklichen Kreaturen noch einmal unterwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83832] = { id = 83832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerfetzte Träume", description = "Da seid Ihr ja wieder! Ich könnte wirklich Eure Hilfe brauchen.\n\nZeitteufel, die gestern Abend hier durchgeflitzt sind, haben das Buch einer Besucherin namens Addie Zischmoor beschädigt. Ich kümmere mich gerade noch um die anderen Probleme, die sie verursacht haben, und hoffe nun, dass Ihr Addie unter die Arme greifen könnt.", sourceObjective = "Sucht Raenie Zischmoor vor den Höhlen der Zeit auf.", completion = "DER Hemet Nesingwary ist hier, um sein Buch \"Die Grünen Hügel des Schlingendorntals\" zu signieren. Ich wollte ihm mein Exemplar davon überreichen, doch dann sind Sandteufel durch das Lager gefegt und haben mein Buch zerfetzt!\n\nMeine Schwester will nicht, dass ich das Lager alleine verlasse, und ich traue mich nicht, ihr zu sagen, dass das Exemplar, das sie mir geschenkt hat, nun im Eimer ist. Ich könnte wirklich Eure Hilfe brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83930] = { id = 83930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurmkurlösung" }
quests[83931] = { id = 83931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramponierte Feierkiste", description = "<Die Kiste ist ziemlich ramponiert. Offenbar hat mindestens ein Wolf an einer der Ecken genagt. Alyx würde sich über die Vorräte freuen.>", sourceObjective = "Bringt die ramponierte Feierkiste zu Alyx zurück.", progress = "Oh, ich habe so viel zu tun. Doch womit kann ich Euch helfen?", completion = "Oh, Ihr habt noch eine unserer fehlenden Kisten gefunden!\n\nEs sieht so aus, als hättet Ihr sie gerade noch rechtzeitig gerettet. Nur ein wenig mehr, und das Tier, das in sie hineinwollte, hätte die Vorräte verdorben.\n\nIch bin Euch sehr dankbar, dass Ihr sie mir gebracht habt. Wenn Ihr noch welche finden solltet, bringt sie mir bitte auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[83932] = { id = 83932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historische Dokumente", description = "Stellt Euch vor, die Chance zu haben, Himmelskapitänin Elaena Lancekat auf ein so großes Abenteuer zu begleiten. So eine Chance bietet sich im Leben nur einmal!\n\nAber wenn ich ein Buch über diese Reise schreiben will, sollte ich wohl ein paar historische Informationen über diese Insel zusammentragen.\n\nVielleicht könntet Ihr ein paar Notizen oder Dokumente sammeln? Wir können alles brauchen, was uns etwas über die Geschichte dieses Ortes erzählt!", sourceObjective = "Fügt 12 Notizen und Dokumente, die Ihr auf der Insel gefunden habt, zu den Forschungsaufzeichnungen hinzu.", completion = "Ihr habt so viele wertvolle Informationen zusammengetragen - unglaublich, was hier alles an Geheimnissen zu finden ist!\n\nIch kann es kaum erwarten, dieses Buch zu schreiben.\n\nIch muss mir nur noch den perfekten Titel einfallen lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[83933] = { id = 83933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kaja'Küste", description = "Gut, wir haben die Stempelkarte zur Kaja'Küste und einen ziemlich guten Grund, zu glauben, dass die Venture Company Gallywix mehr Honig um den Bart schmiert, als wir dachten.\n\nNoggenfogger sagte, wir würden Antworten in den Minen finden, und das bedeutet, uns an der Kaja'Küste umzusehen.\n\nGehen wir. Wir treffen uns in der Schmetterzentrale.", sourceObjective = "Trefft Gazlowe und Renzik am Bahnhof Schmetterzentrale, dann nutzt den küstenseitigen Bohrer, um zur Kaja'Küste zu reisen.", completion = "Die Düsternisverschmolzenen beobachten diesen Ort.\n\nSie verstecken irgendwas hier. Was Großes.", sourceObjectiveStatus = "unverified-source-field" }
quests[84001] = { id = 84001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Loren verloren", description = "Unsere Bergarbeiter kommen gut voran. Unsere Loren wurden bereits voller Erzproben ins Lager zurückgeschickt.\n\nAber es gibt da ein Problem...\n\nAufgrund der defekten Gleise hat keine der Loren das Lager bisher erreicht!\n\nBitte repariert die Gleise und sammelt all das heruntergefalle Erz ein, damit wir die Proben ins Lager bringen können.", sourceObjective = "Repariert 2 Minengleise, räumt 5 verunglückte Minenloren und sammelt 12 Erzproben.", progress = "Kommen die Minenloren jetzt durch?", completion = "Ausgezeichnete Arbeit, {name}. Ich wusste, Ihr findet einen Weg, um dieses Problem zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84020] = { id = 84020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mech in Not", description = "Dieser Mechanzug hat schon bessere Tage gesehen. Vielleicht kann Euch ein erfahrener Maschinenflüsterer helfen. \n\nIch weiß, dass Sprecher Jurlax in letzter Zeit Maschinisten für die Wartung von Mechanzügen abgestellt hat. Er hat bestimmt einen Rat für Euch.", sourceObjective = "Bringt den defekten Mechanzug zu Sprecher Jurlax in Gundargaz.", completion = "Zeit und Verfall haben dieser Maschine zugesetzt.\n\nMit ein bisschen Arbeit können wir sie vielleicht noch retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84021] = { id = 84021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Rädchen im Getriebe", description = "Diagnose: Diese Maschine ist in ihrer Beweglichkeit beeinträchtigt.\n\nWir müssen sie wieder in Gang bringen. Ich brauche ein paar Ersatzteile. Die Zahnräder müssen weiter laufen.", sourceObjective = "Bringt Sprecher Jurlax einen übertakteten Zahnradbumerangwerfer für Ersatzteile.", progress = "Habt Ihr die Teile, die wir brauchen?", completion = "Genau das, was ich brauche: das richtige Teil für den richtigen Job. \n\nDas sollte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[84022] = { id = 84022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchtrennte Fäden zusammenführen", description = "Ihr habt gute Arbeit geleistet, als Ihr Anub'azal und Nizrek als Verbündete für unsere Sache gewonnen habt.\n\nEs wird Zeit, dass wir diese Dreiecksbeziehung zwischen uns allen verfestigen. Wir werden per Schattenwerfer konferieren. Aktiviert sie, wenn Ihr bereit seid.", sourceObjective = "Schließt Euch mit der Weberin, dem General und dem Wesir zusammen, um die Durchtrennten Fäden zu schmieden.", progress = "Ich frage mich, wie unsere drei mächtigen Persönlichkeiten zusammenarbeiten werden. Die Zeit wird es zeigen, schätze ich.", completion = "Ich hatte mehr hitzige Debatten erwartet, als wir erlebt haben. Dass alle so bereitwillig zusammenarbeiten, muss bedeuten, dass die Zeiten wirklich düster sind.\n\nWir haben einen weiten Weg vor uns. Ich muss klar sagen, dass Eure Hilfe unschätzbar wertvoll war. Vielleicht wird sie zu jenem Faden, der meinem Volk das Überleben sichert.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[84023] = { id = 84023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientierung finden", description = "Die Maschinen bewegen sich ohne Intention.\n\nLasst sie uns zu einer Bestimmung hinführen.\n\nWeist diesem Gerät eine Richtung.", sourceObjective = "Bringt Sprecher Jurlax einen synergetischen Gebräuterialisator für Ersatzteile.", progress = "Ist Euch räumliche Allwissenheit beschert?", completion = "Dies leitet uns den Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[84024] = { id = 84024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle ergreifen", description = "Die Maschine atmet ohne Leben.\n\nWir müssen ihr unser Leben einhauchen.\n\nFindet einen Leiter für den Willen des Göttlichen.", sourceObjective = "Bringt Sprecher Jurlax einen Stichel des Kerzenkönigs für Ersatzteile.", progress = "Ist Euch ein Werkzeug der Einflussnahme gegeben?", completion = "Dies kanalisiert unsere Prädilektion.", sourceObjectiveStatus = "unverified-source-field" }
quests[84025] = { id = 84025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umfunktioniert und wiederhergestellt", sourceObjective = "Die Maschine ist neu geboren, ihr Zweck wiederhergestellt.\n\nEuch, der ihr Leiden gestillt hat, obliegt es nun, diesen Zweck weiterzutragen.\n\nMöge ihr Metall nie nachgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84084] = { id = 84084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine Prise", description = "Staub ist das Fundament der Verzauberungskunst. Wo Verzauberungsneulinge ob dieses banalen Materials die Nase rümpfen, verstehen Meister seine Vielseitigkeit.\n\nBringt mir Sturmstaub. So weit unsere Expertise auch reichen möge, wir müssen stets zu den Grundlagen zurückkehren.", sourceObjective = "Sammelt 20 Sturmstaub und bringt sie zu Nagad in Dornogal.", progress = "Habt Ihr den nötigen Staub gesammelt?", completion = "Mein Dank. Ich freue mich sehr, einen Verzaubererkollegen zu sehen, der die Grundlagen zu schätzen weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[84085] = { id = 84085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Möglichkeit", description = "Wir Verzauberer handeln nicht bloß mit Runen oder Zauberstäben. Unsere eigentliche Handelsware ist Potenzial. Wir nehmen die Macht der Möglichkeit und verwandeln sie in etwas Greifbares.\n\nFür diesen Vorgang brauchen wir glänzende Scherben. Ich benötige einige davon, um meine Arbeit fortzusetzen.", sourceObjective = "Sammelt 10 glänzende Scherben und bringt sie zu Nagad in Dornogal.", progress = "Da, wo Staub Vielseitigkeit bringt, wo Scherben Potenzial bieten.", completion = "Beifallsruf. Diese werden viele nützliche Verzauberungen antreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84086] = { id = 84086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltene Notwendigkeit", description = "Hin und wieder sucht man uns in dem Verlangen nach unseren großartigsten und mächtigsten Segen auf. Für diese benötige ich einen glänzenden Kristall.\n\nJa, derartige Kristalle sind selten. Doch um die Perfektion unseres Handwerks zu erreichen, sind die unverzichtbar. Habt keine Sorge, er wird nicht verschwendet.", sourceObjective = "Sammelt 1 glänzenden Kristall und bringt ihn zu Nagad in Dornogal.", progress = "Sobald ich ihn in der Hand halte, sorge ich dafür, dass er für einen guten Zweck zum Einsatz kommt.", completion = "Wunderschön, nicht? Ihr erahnt sicher das Potenzial, das dadurch freigesetzt werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[84087] = { id = 84087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 26" }
