quests[84121] = { id = 84121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kleine Absicherung", description = "Zu viele Düsternisverschmolzene bewachen diesen Ort, um an ihnen vorbei zu schleichen. Wir werden sie auf altmodischem Wege ausdünnen müssen.\n\nErledigt so viele Düsternisverschmolzene wie möglich. Gazlowe und ich gehen auf Erkundung.", sourceObjective = "Tötet 10 Düsternisverschmolzene an der Kaja'Küste.", completion = "Das wird vorerst reichen. Wenigstens haben wir etwas Platz, um einen Plan zu schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84122] = { id = 84122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kameras aus", description = "Gallywix ist nicht dumm. Er hat diese Überwachungsvögel, die ein Auge auf das ganze Gebiet haben.\n\nWir müssen sie vom Netz nehmen, wenn wir verborgen bleiben wollen - und damit meine ich, wir müssen sie in klitzekleine Teile schlagen.\n\nWenn Ihr Hilfe dabei braucht, sie aus der Luft zu fangen, nutzt meinen automatischen Greifarm. Oh, und sammelt einige ihrer Teile für mich ein, wenn Ihr fertig seid. Ich habe eine Idee.", sourceObjective = "Sammelt 6 Handvoll V.O.G.E.L.-Teile von Überwachungs-V.O.G.E.L.-Einheiten an der Kaja'Küste ein.", progress = "Ich bin mir nicht sicher, warum sie eine Mine so streng bewachen, aber wir müssen dafür sorgen, dass sie weniger genau hinsehen.", completion = "Ich habe diesen V.O.G.E.L. weitestgehend ausgeweidet.\n\nGemeinsam sollten wir in der Lage sein, diese Teile auseinanderzunehmen, um daraus ein neues Innenleben zu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84123] = { id = 84123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test" }
quests[84127] = { id = 84127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekünste sind gefragt", description = "Grüße, {class}. Das Handwerkerkonsortium sucht nach talentierten Kunsthandwerkern für Aufträge von lokalen Kunden.\n\nWenn Ihr meint, dass Eure Arbeit unseren Standards und unserer Qualität entspricht, versucht bitte, einige unserer öffentlichen Aufträge auszuführen. Ihr könnt auch Aufträge für eigene Gönner, Gildenaufträge oder persönliche Aufträge ausführen.\n\nSprecht mit mir, wenn Ihr Eure Entwürfe fertiggestellt habt. Möge der Wind Eure Hände und Euer Herz leiten.", sourceObjective = "Erfüllt Schmiedekunstaufträge für das Handwerkerkonsortium.", progress = "Sprecht mit mir, wenn Ihr Eure Entwürfe fertiggestellt habt. Möge der Wind Eure Hände und Euer Herz leiten.", completion = "Danke für das Erfüllen dieser Aufträge. Unsere Kunden werden sehr zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
