quests[84140] = { id = 84140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mach-ich-Caddie", description = "Meine \"Firma\" wurde also beauftragt, den Golfplatz hier zu betreuen.\n\nNur hat sich herausgestellt, dass die Materialien, die wir für unser patentiertes explosionssicheres Gras verwendet haben, einen Schwarm von Kurshasen angelockt hat. Unglücklicherweise ist das eine der einzigen Nagetierarten, die das Gras fressen kann.\n\nIch brauche einen Mach-ich-Caddie, den ich mit der Beseitigung dieser Bedrohung für mein Geschäft beauftragen kann. Also, könnt Ihr das tun?", sourceObjective = "Beseitigt 9 Kurshasen.", completion = "Gute Arbeit! Jetzt wird das Geld reinkommen. Moment mal... Was war das für ein Geräusch?", sourceObjectiveStatus = "unverified-source-field" }
quests[84141] = { id = 84141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrugshülsen", description = "Hört mal, ich betreibe hier ein seriöses Geschäft... wenn ich dafür bezahlt werde.\n\nAber 'ne ganze Reihe von hinterhältigen Taugenichtsen versucht, Betrugshülsen in den Löchern zu platzieren. Die Dinger zieh'n die Bälle der Betrüger an und machen das Spiel kaputt.\n\nDas geht nicht.\n\nFindet die Betrugshülsen und beseitigt sie.", sourceObjective = "Entfernt 4 Betrugshülsen.", completion = "Großartige Arbeit! Ehrlich gesagt, wer so etwas macht, kommt in meine engere Auswahl von Leuten, die ich in Ratten verwandeln möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[84142] = { id = 84142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doch noch ein Loch", description = "Gut, nun, da das geklärt ist, wie wäre es mit einem kostenlosen Abschlag, hm?\n\nHier auf dem...\n\n<Zocknudel hält inne, um auf die Notizen zu schauen, die er aus seiner Hosentasche zieht.>\n\nGolfplatz Smaragdhügel sind wir stolz darauf, dass jeder einen Volltreffer schafft!\n\nVor allem, weil unsere Bummkugeln nach dem ersten Schlag explodieren. Also gebt alles.\n\n Nehmt Euch ein paar Bälle und schlagt los.", sourceObjective = "Versenkt 4 Bummkugeln in den vier Golflöchern.", progress = "Neulich sah ich einen Hexenmeister, der seinen Wichtel dazu bringen wollte, einen Ball in das Loch zu stoßen. Mann, dieser Wichtel war NICHT glücklich, als er nach der Explosion zurückgerufen wurde.\n\nWofür man nicht so alles seine Seele verkauft...", completion = "Das war äußerst beeindruckend!", sourceObjectiveStatus = "unverified-source-field" }
quests[84143] = { id = 84143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren und beschäftigt", description = "Dem Licht sei Dank, ein Wagehals!\n\nBitte, Ihr müsst mir helfen. Veranstaltungsplanung ist selbst unter den besten Umständen eine grauenvolle Arbeit. Gerade folgt auf eine Krise die nächste!\n\nEs gibt da ein kleines Tuskarrkind, das Hilfe benötigt, aber ich habe hier alle Hände voll zu tun. Als ich das Mädchen das letzte Mal sah, ging es in Richtung von Leeroys Hühnchen.", sourceObjective = "Findet Maru in der Nähe von Leeroys Hühnchen.", completion = "Szeid Ihr hier, um szu helfen? Mein Bwuder hat szein Sznüffel-Tingszda verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[84144] = { id = 84144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tieszer grosze Fieszling", description = "Tieszer grosze Fieszling hat tasz Sznüffel-Tingszda von meinem Bwuder gesztohlen! Wir müszen rauszfinden, wer esz geweszen ist und esz wieder szurückholen!\n\nIchz tenke, ezs ging hinter dem Topf ta hinten verloren.\n\nHier, mein Onkel hat tieszen alten Vogelgötszen. Ter szucht nach Hinweiszen! Ichz borge ihn Euchz, denn Ihr szeht ausz wie jemand, ter helfen will.", sourceObjective = "Nutzt den Götzen von Ohn'ahra, um nach Hinweisen in der Nähe des Plumpsklos zu suchen.", progress = "Habt Ihr Hinweisze gefunden? Wir müszen tieszen groszen Fieszling finden!", completion = "Ihr habt esz gefunden! Euchz liegt dasz Sznüffeln im Blut.\n\nIhr könnt ten Götszen ersztmal behalten. Vielleichzt hilft er unsz dabei, noch andere Fälle szu löszen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84214] = { id = 84214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Auftrag", description = "Ihr wollt Geld? Ihr könnt gut Sachen zerschlagen und ein leicht unmoralischer Reichtumserwerb macht Euch keine Angst?\n\nDann hat die Entrepreneur AG einen Auftrag für Euch!\n\nKommt in unser Hauptquartier auf dem Hügel und sprecht mit Skedgit Glutfransen, um weitere Einzelheiten zu erfahren.", sourceObjective = "Sprecht mit Skedgit Glutfransen auf dem Hügel.", completion = "Oh, meine Güte! Ich hatte eigentlich jemanden von hier erwartet, aber Ihr seid perfekt für diesen Auftrag.\n\nWisst Ihr... Es geht weniger um einen \"Auftrag\" und mehr um einen \"Raub\".", sourceObjectiveStatus = "unverified-source-field" }
quests[84215] = { id = 84215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mannschaft", description = "Ihr seid angeheuert!\n\nGut, mein geplanter Raubüberfall wird uns eine Menge Geld einbringen, erfordert aber eine Mannschaft und viel Planung.\n\nIch kümmere mich um die Planung, Ihr um die Mannschaft.\n\nWir brauchen Goldmine. Außerhalb der Venture Company ist er einer der schnellsten Fahrer. Weil er nicht zur Venture Company gehört, kann er nicht zu mir zurückverfolgt werden.\n\nWir brauchen auch ein Gesicht, zu dem kein Schläger Nein sagen kann. Wir brauchen den hübschen Crog.\n\nOh, und ich brauche meinen Cousin Zocknudel. Er ist nicht der beste Magier, aber er ist Teil der Familie. Und mein Boss.", sourceObjective = "Versammelt die Mannschaft.", completion = "Sie sind gekommen? Großartig!\n\nIch wusste, Ihr würdet sie für uns gewinnen! Hätten sie mich gesehen, hätten sie sich vielleicht erinnert...\n\nAber lasst uns nicht an die Vergangenheit denken.", sourceObjectiveStatus = "unverified-source-field" }
quests[84216] = { id = 84216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel", description = "Ich werde Euch die Details des Plans erläutern.\n\nAber hier ist die Version für Ungeduldige:\n\nWir treffen uns vor der Luftschiffstation im Bezirk von Bilgewasser.\n\nDer hübsche Crog hilft uns, an den Wachen vorbei zum Luftschiff-Versorgungsballon zu gelangen.\n\nWir stehlen den Ballon und verschaffen uns damit Zutritt zum Luftschiff über der Arena, wo sich der Safe mit der ganzen Beute befindet.\n\nBereit?", sourceObjective = "Stehlt einen Luftschiff-Versorgungsballon.", completion = "Das war der leichte Teil.", sourceObjectiveStatus = "unverified-source-field" }
quests[84217] = { id = 84217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch hinaus", description = "Gut, wir schaffen das.\n\nIhr, ich und das Großmaul hier werden auf diesem Ballon zum Luftschiff über der Arena aufsteigen.\n\nDort wird die Beute aufbewahrt. An Bord wird der Platz zum Kämpfen begrenzt sein. Ich habe uns ein paar Uniformen besorgt, damit wir wie Leute aussehen, die dort arbeiten, aber versucht, keinen Streit anzufangen.\n\nBereit?", sourceObjective = "Erreicht den Safe.", completion = "Gut, das \"wirkt\" vielleicht nicht wie Beute, aber ich verspreche Euch... na ja... ähm....\n\nWenn wir hier rauskommen, revanchiere ich mich irgendwie, das schwöre ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[84218] = { id = 84218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluchtwagen", description = "Gut... ähm... Ich habe \"vielleicht\" über die Beute gelogen.\n\nIhr könnt so wütend auf mich sein, wie Ihr wollt, aber wir müssen jetzt los.\n\nSteigt ein! Wir müssen Gas geben!", sourceObjective = "Entkommt im Fluchtwagen.", completion = "Es tut mir leid, wenn Ihr Euch Hoffnungen auf die Beute gemacht habt. Ich...\n\nIch konnte meine Großmutter nicht ohne Hilfe aus den Klauen der Düsternisverschmolzenen befreien. Und Menschen TUN nicht einfach etwas umsonst oder weil es eine gute Tat ist.\n\nAlso... ähm... hier. Das ist alles, was ich habe, und Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[84220] = { id = 84220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchgang zu den Schallenden Tiefen", sourceObjective = "Vielen Dank für alles, was Ihr auf der Insel von Dorn getan habt.\n\nRatsvorsteher Merrix hat die Wiederherstellung dieses Aufzugs angeordnet, um unsere Verbündeten weiter zu unterstützen und sicherzustellen, dass wir nicht noch einmal vollständig abgeschnitten werden.\n\nDamit könnt Ihr schnell in die Schallenden Tiefen und zurück reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84221] = { id = 84221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papierkram lässt die Lore sinken", description = "Ich bin Marty. Marty Rennraser. Marty Rennraser, Pflichtverteidiger und Beauftragter für den Fall Garbagio im Auftrag des Staates Lorenhall.\n\nWas für ein Zungenbrecher... Nennt mich einfach Marty.\n\nDer Inhaber der Urkunde, Rosenknospe Gallywix, ist also tot? Und niemand weiß, wer der Mörder ist. Und irgendein Niemand, Ihr, habt die Urkunde? Ehrlich gesagt, ist das kein ungewöhnlicher Vorfall. Es gibt viele Präzedenzfälle. Nur keine Zeit...\n\nEs sieht folgendermaßen aus: Wenn wir der Urkunde keine neuen Eigentümer beifügen, wird sie wie eine jahrzehntealte Hose versteigert.", sourceObjective = "Erstellt einen Plan, um das Garbagio vor dem Auktionshaus zu bewahren.", progress = "Normalerweise mische ich mich nicht gerne in große Geschäfte ein.\n\nAber das Garbagio ist eine wichtige Einrichtung für die Leute von Lorenhall.", completion = "Wir haben eine schwierige Aufgabe vor uns.\n\nAber keine Angst. Wir werden einen Schritt nach dem anderen tun und eine Lösung finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84222] = { id = 84222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert die Umgebung", description = "Eine Vielzahl gefährlicher Kreaturen hat unser Lager hier angegriffen.\n\nWährend meine Truppen mit den meisten Bedrohungen fertig werden können, erfordern einige der mächtigeren Kreaturen Euer Fachwissen.\n\nDurchkämmt die Insel und eliminiert alle mächtigen Wesen, die unsere Operationen hier gefährden könnten.", sourceObjective = "Eliminiert 2 seltene Gegner auf der Sireneninsel.", progress = "Wie läuft die Jagd? Ist unser Lager jetzt sicher?", completion = "Gute Arbeit, {name}. Ich könnte jemanden wie Euch in meiner Mannschaft gebrauchen. Schade, dass Ihr kein Arathi seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[84223] = { id = 84223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuldgefühle der Überlebenden", description = "Wir alle haben unter Xal'ataths Taten gelitten, manche mehr als andere.\n\nIch bin froh, am Leben zu sein, auch wenn ich mich jetzt so alt fühle, wie ich aussehe.\n\n<Khadgar versucht zu lachen, muss stattdessen aber husten. Er winkt Eure Sorgen ab.>\n\nMacht Euch keine Sorgen um mich. Aber Aethas...\n\nIch habe gehört, dass er zur Absturzstelle von Dalaran zurückgekehrt ist. Und dass er seit unserer Ankunft weder geschlafen noch gegessen hat.\n\nEr will meine Hilfe, aber ich konnte mich noch nicht dazu durchringen, zur Absturzstelle zu gehen.\n\nWürdet Ihr an meiner Stelle gehen?", sourceObjective = "Findet Aethas Sonnenhäscher am Ruhigen Ufer.", completion = "<Aethas' Körperhaltung ist von der Erschöpfung schlafloser Nächte und Tage ohne Nahrung gezeichnet. Seine zerfledderte Kleidung hängt lose von seinem ausgemergelten Körper und jede seiner Bewegungen wirkt müde.>\n\nIch verstehe. Ich wusste, dass Khadgar schwer verletzt war, aber mir war nicht klar, dass seine Wunden mehr als nur körperlicher Natur sind.\n\nIch respektiere seine Entscheidung, nicht hierherzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84224] = { id = 84224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen!", description = "In den Tiefen gibt es noch mehr zu tun, {name}!\n\nTrefft mich in Dornogal. Es gibt viel zu bereden!", sourceObjective = "Trefft Euch mit Brann Bronzebart in Dornogal.", completion = "Schön, dass Ihr hier seid! Wir haben jede Menge zu bereden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84225] = { id = 84225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ver-ei-teln", description = "Wir sollten fliehen, aber...\n\nseht Ihr die Eier da drüben? Wenn die Monster sie alle ausbrüten, wird es hier von Krabben wimmeln, wenn sich der Sturm legt.\n\nPuh, es sind einfach zu viele, um sie von Hand zu vernichten. Wir werden Hilfe brauchen!\n\nSusi hat eine Menge nützlicher Gegenstände im Lager... oder nehmt meinen Bräter. Keine Ahnung. Nehmt Euch irgendetwas, womit Ihr diese Eier vernichten könnt!", sourceObjective = "Vernichtet 12 Eierhüter und 12 Brutgelege.", progress = "Habt Ihr die Eier vernichtet?", completion = "Ich wusste, Ihr kümmert Euch um dieses gruselige Chaos!", sourceObjectiveStatus = "unverified-source-field" }
quests[84236] = { id = 84236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Detektiv", description = "<Abenteurer/Abenteurerin>, dem Licht sei Dank, dass Ihr hier seid. Wir vermissen einen unserer Gäste.\n\nEin Detektiv untersucht den Fall, aber ich habe noch keine Rückmeldung. Könntet Ihr ihn bitte fragen?", sourceObjective = "Sprecht mit Detektiv Jones.", completion = "Ja, sicher könnt Ihr ein Autogramm haben.\n\nHm? Darum seid Ihr nicht hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[84237] = { id = 84237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der \"große\" Detektiv", description = "Der vermisste Gast? Ja, ein gewisser Herrkrop. Keine Bange, ich habe den Fall schon gelöst.\n\nWahrscheinlich hat er sich nur verlaufen. Entspannt Euch, {class}. Genießt die Feierlichkeiten! Unser vermisster Gast wird schon rechtzeitig auftauchen.\n\nWenn Ihr mir nicht glaubt, dann... ja, dann löst den Fall doch selbst. Verhört einen Verdächtigen. Oder mehrere.", sourceObjective = "Löst das Rätsel hinter Herrkrops Verschwinden.", progress = "Habt Ihr unseren vermissten Gast schon gefunden?", completion = "Ach, das ist also passiert?\n\n<Alyx seufzt.>\n\nDanke für Eure Hilfe. Ich versuche jetzt, einen Hinweis zu auf Schrapps Aufenthaltsort zu finden.\n\nKommt doch bitte morgen wieder vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[84241] = { id = 84241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küstenkoalition", description = "Dieser Sturm wird mich nicht von meiner heiligen Pflicht abbringen. Diese Höhle muss um jeden Preis verteidigt werden!\n\nDieser neue Kristall mag noch immer geheimnisumwittert sein, aber wir werden seine Geheimnisse oder seine Beziehung zu Beledar nie verstehen, wenn wir zulassen, dass er in die Hände dieser Schurken fällt, die aus dem Abgrund des Ozeans kriechen.\n\nSteht mir bei, {name}. Gemeinsam werden wir diese Küste bis zu unserem letzten Atemzug verteidigen.", sourceObjective = "Vernichtet 15 salzgebundene Gespenster und Gezeitenchampion Korval.", progress = "Ist der Kristall in Sicherheit?", completion = "Guter Kampf. Eure Hilfe war sehr willkommen, {name}. Die Heilige Flamme hat unsere Hand und unseren Stahl geführt.\n\n\nAber jetzt habe ich die Situation unter Kontrolle. Vielleicht brauchen ein paar der noch verbliebenen Goblins oder Irdenen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[84242] = { id = 84242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haldentauchgang", description = "Unser erstes Ziel sind die Spielerknaller Kayjay und der fantastische Davey.\n\nEs ist schon ein paar Jahre her, dass ich in den Elektrobillardsälen Makronen hin und her geschoben habe. Ich war nicht schlecht, aber die beiden haben das Haus ausgeräumt, wann immer sie auftauchten.\n\nSie gewinnen auch nicht nur Spiele. Sie machen sie! Echte Künstler, versteht Ihr?\n\nAber mit großen Spielen kommen auch große Schulden. Und die sind in der Regel bei der Venture Company.\n\nWir treffen uns bei den Halden. Wenn sie durch Rosenknospes Tod arbeitslos geworden sind, würde ich Geld darauf wetten, dass Venture sie wieder aufgesammelt hat.", sourceObjective = "Trefft Euch mit Marty Rennraser bei der Venturemühle auf den Halden.", completion = "{name}! Ihr seid ja pünktlich wie ein Mechagnom. Wie ein Uhrwerk.", sourceObjectiveStatus = "unverified-source-field" }
quests[84244] = { id = 84244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmeerstrandwelle", description = "Ihr habt mit Jojo gute Arbeit geleistet. Wirklich gut. \n\nIch bleibe in der Nähe, besiegle die Sache und treffe Euch dann drüben in der Marina der Schwarzmeer AG für die endgültige Unterschrift. \n\nIch hatte mein Radio auf WGOB 101.1 FM eingestellt, als ich vorhin die fünfzehn nach Müll riechenden Leute absetzte. DJ B. B. Rev kündigte an, dass es heute ein Bandwettbewerb an der Marina geben würde. \n\nWer hätte das gedacht, Rosenknospes leitende Entertainmentangestellte spielt mit! Die Band, die Ihr sucht, sind die Kellergnome.", sourceObjective = "Trefft Marty Rennraser in der Marina der Schwarzmeer AG.", completion = "Ich habe versucht, mit der Gnomin zu sprechen, aber sie ist ziemlich abgelenkt. \n\nVersucht Ihr es bitte mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[84246] = { id = 84246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezeugung der Brillanz", description = "Die Zeit ist endlich gekommen und der Moment könnte nicht inspirierender sein. Wir müssen jetzt an die Arbeit.\n\nKommt zu mir nach draußen. Wir sehen uns die Früchte unserer Arbeit an.", sourceObjective = "Werdet Zeuge von Siesbargs Aufstieg.", completion = "Also, das hatte ich mir anders vorgestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84248] = { id = 84248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ritual der Runen", description = "Ich habe eine nahe gelegene Höhle erkundet und bin dabei einigen Vrykul der Blutgischt begegnet, die irgendetwas beschworen haben... etwas, das meine Protokolle zur Gefahrenabwehr aktiviert hat.\n\nIch glaube, dass es katastrophale Folgen für die Insel haben dürfte, sollten sie ihr Ritual beenden können.\n\n{name}, bitte geht in die Höhle und haltet ihr Ritual auf, bevor etwas Schreckliches geschieht!", sourceObjective = "Zerstört 5 Beschwörungsrunen und besiegt Inhyldir die Verfluchte.", progress = "Konntet Ihr das Ritual stören?", completion = "Das war knapp. Wir müssen auf der Hut bleiben und nach merkwürdigen Aktivitäten Ausschau halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84249] = { id = 84249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fass mit Boden", description = "Unser nächstes Ziel ist Jojo Gobdre, in den Bottichwerken. \n\nSie war eine Spitzenköchin. Die einzig Wahre. Und die Küche im Garbagio zu leiten, hätte Franchise-Möglichkeiten bedeutet. Gibt es einen Grund, warum sie Rosenknospe tot sehen wollte?\n\nWie auch immer, wir brauchen einen Hinweis, wo sie im Moment kocht. Zum Glück habe ich einen alten Freund, der Informationen haben sollte. Er ist eine Art Zampano im Dampfdruckkartell, aber wir sollten in der Lage sein, ihn auf seinem Dachversteck aufzuspüren.\n\nWir treffen uns dort. Bringt Hunger mit.", sourceObjective = "Trefft Marty Rennraser in den Bottichwerken.", completion = "Nehmt bitte Platz, {name}!\n\nKennt Ihr meinen Kumpel Noggy schon? Er und ich kennen uns schon lange. Wir waren Zimmergenossen auf der Handelshochschule. \n\nWir haben damals einige verrückte Dinge getan, aber das ist jetzt nicht der Rede wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[84252] = { id = 84252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höchste Präzision", description = "Fliegen? Nichts für mich.\n\nSally Bolzschraub wollte, dass ich ein paar Theodolite aktiviere, um die Windströmungen zu überwachen, aber da oben ist es einfach zu rau und ich habe Höhenangst.\n\nSobald ich es nur versuche, wird mir schlecht.\n\nVerwendet die Tasche, um die Maschinen zu aktivieren. Ihr habt was gut bei mir!", sourceObjective = "Verwendet die experimentelle Tasche, um die Theodoliten zu erreichen und aktiviert 6 von ihnen.", completion = "Danke, dass Ihr Benny ausgeholfen habt. Ihr könnt Euch die Tasche jederzeit ausleihen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84254] = { id = 84254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schöne Grüße", description = "Seid gegrüßt und fröhliches Jubiläum!\n\nIch bin Yllana, die Dirigentin dieser Symphonie der Feierlichkeit. Gehe ich recht in der Annahme, dass es Euch bereits nach Spaß und Unterhaltung dürstet? Nun, dann keine Sorge, denn es gibt nicht nur viel zu tun, sondern auch viel Zeit, um es zu tun.\n\nIch habe auf Eurer Karte die Positionen meiner freudigen Begrüßer markiert, die Euch alles über die Aktivitäten erzählen können, die Euch erwarten.\n\nKommt zu mir zurück, sobald Ihr mit ihnen geredet habt, dann gebe ich Euch ein Geschenk, das Eure Freudigkeit auf die höchste Stufe hebt. Was wäre schließlich eine Feier ohne Geschenke?", sourceObjective = "Sprecht mit den Begrüßern für die Aktivitäten.", progress = "Es ist leicht, sich ablenken zu lassen. Habt Ihr mit den Begrüßern für die Aktivitäten gesprochen, von denen ich Euch erzählt habe?", completion = "Ich nehmen an, dass Ihr etwas gefunden habt, das Euch bei Laune hält, während Ihr mit uns feiert.\n\nWie versprochen, hier ist Euer Geschenk.\n\n<Yllana reicht Euch eine kleine, festliche Tasche, deren Inhalt nicht gerade wenig wiegt. Was auch immer sich darin befindet fühlt sich teuer an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[84260] = { id = 84260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerk laut Auftrag", description = "Hallo, seid gegrüßt – herzlich willkommen in der Handwerksenklave.\n\nLaut Marktvögtin Vokgret arbeiten wir jetzt mit dem Handwerkerkonsortium zusammen, um die Bedürfnisse der Irdenen und der Fremdlinge zu befriedigen.\n\nBitte sprecht mit Ardran oder Pordaz, um Handwerksaufträge anzusehen und zu vergeben.", sourceObjective = "Sprecht mit Ardran in der Handwerksenklave.", progress = "Habt Ihr mit Ardran gesprochen?", completion = "Diese Arbeitsaufträge sind sehr nützlich. Ich weiß gar nicht, wieso wir nicht schon vor der Ankunft der Fremdlinge daran gedacht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84274] = { id = 84274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Schmiedekunst", description = "Ihr versteht Euch also auf Schmiedekunst? Das hättet Ihr eher erwähnen sollen!\n\nIch schicke Euch zu Darean, einer hoch angesehenen Schmiedin, die ihre Werkstatt in den Schmiedegründen hat. Ich werde den Ort auf Eurer Karte markieren.\n\nDarean hat einen eigenen Schmiedetisch, an dem Ihr Arbeitsaufträge aus öffentlichen Listen und persönlichen Kontakten wie Freunden und Gildenkollegen prüfen, herstellen und ausliefern könnt. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet. Zumindest habe ich schon davon gehört.", sourceObjective = "Findet Darean in den Schmiedegründen und verwendet ihren Schmiedetisch.", progress = "Scheut Euch nicht davor, meinen Schmiedetisch zu verwenden, falls Ihr Bedarf habt.", completion = "Ich bin erfreut, dass wir gemeinsam unsere Weisungen vorantreiben konnten!", sourceObjectiveStatus = "unverified-source-field" }
quests[84278] = { id = 84278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest", description = "Gute Nachricht! Wir haben einen Hinweis. Rexxar will uns bei der Suche nach Schrapp helfen. Wenn einer diesen untoten Mörder finden kann, dann er.\n\nRexxar ist der Fährte in die Boreanische Tundra gefolgt. Er hat diesen Zettel für Euch dagelassen.", sourceObjective = "Folgt den Koordinaten auf dem Zettel zu Rexxars Standort in der Boreanischen Tundra.", completion = "Gut, Ihr habt mich gefunden. Jetzt kann die Jagd beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84279] = { id = 84279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Juwelierskunst", description = "Ihr versteht Euch also auf Juwelierskunst? Das hättet Ihr eher erwähnen sollen!\n\nIch schicke Euch zu Makir, einem hoch angesehenen Juwelenschleifer, der eine Werkstatt in den südlichen Schmiedegründen hat. Ich werde den Ort auf Eurer Karte markieren.\n\nMakir hat eine eigene Juwelierswerkbank, an der Ihr Arbeitsaufträge aus öffentlichen Listen und persönlichen Kontakten wie Freunden und Gildenkollegen prüfen, herstellen und ausliefern könnt. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet. Zumindest habe ich schon davon gehört.", sourceObjective = "Sucht Makir in den Schmiedegründen auf und verwendet seine Werkbank des Juweliers.", progress = "Scheut Euch nicht davor, meine Juwelierswerkbank zu verwenden, falls Ihr Bedarf habt.", completion = "Kommt bald wieder! Es gibt immer was zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[84280] = { id = 84280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Lederverarbeitung", description = "Ihr versteht Euch also auf Lederverarbeitung? Das hättet Ihr eher erwähnen sollen!\n\nIch schicke Euch zu Marbb, einer hoch angesehenen Lederverarbeiterin, die ihre Werkstatt in den östlichen Schmiedegründen hat. Ich werde den Ort auf Eurer Karte markieren.\n\nMarbb hat eine eigene Lederverarbeitungswerkbank, an der Ihr Arbeitsaufträge aus öffentlichen Listen und persönlichen Kontakten wie Freunden und Gildenkollegen prüfen, herstellen und ausliefern könnt. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet. Zumindest habe ich schon davon gehört.", sourceObjective = "Sucht Marbb in den Schmiedegründen auf und verwendet ihre Lederverarbeitungswerkbank.", progress = "Scheut Euch nicht davor, meine Werkbank zu verwenden, falls Ihr Bedarf habt.", completion = "Ich bin froh, dass ich Euch helfen konnte, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84281] = { id = 84281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Schneidern", description = "Ihr versteht Euch also auf Schneiderei? Das hättet Ihr eher erwähnen sollen!\n\nIch schicke Euch zu Kotag, einer hoch angesehenen Schneiderin, die ihre Werkstatt in den östlichen Schmiedegründen hat. Ich werde den Ort auf Eurer Karte markieren.\n\nKotag hat einen eigenen Schneidertisch, an dem Ihr Arbeitsaufträge aus öffentlichen Listen und persönlichen Kontakten wie Freunden und Gildenkollegen prüfen, herstellen und ausliefern könnt. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet. Zumindest habe ich schon davon gehört.", sourceObjective = "Sucht Kotag in den Schmiedegründen auf und verwendet ihren Schneidertisch.", progress = "Nur zu! Ihr dürft an meinem Schneidertisch gerne Maß anlegen.", completion = "Danke, dass Ihr mir erlaubt habt, Euch bei Eurer Weisung zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84285] = { id = 84285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Ingenieurskunst", description = "Ihr... versteht Euch also auf Ingenieurskunst? Hmm!\n\nIhr solltet Euch mit Maschinist Arhdas in den Schmiedegründen kurzschließen. Ich werde den Ort auf Eurer Karte markieren.\n\nArhdas hat einen Ingenieurstisch, an dem Ihr Arbeitsaufträge aus öffentlichen Listen und persönlichen Kontakten wie Freunden und Gildenkollegen prüfen, herstellen und ausliefern könnt. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet. Davon habe ich jedenfalls gehört.", sourceObjective = "Sucht Arhdas in den Schmiedegründen auf und benutzt seinen Ingenieurstisch.", progress = "Meine Werkzeuge und Bank stehen Euch voll zur Verfügung.", completion = "Ich freue mich, jemanden zu treffen, der ebensolches Interesse an meinem Arbeitsgebiet hegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84286] = { id = 84286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schönen Dinge im Leben", progress = "Bringt mir die Insignien der Gäste und Kameraden unserer Königin. Diese sind in der Stadt vielseitig einsetzbar, und im Gegenzug mache ich Euch für unsere Feinde im Inneren noch tödlicher.", completion = "Diejenigen, die mir treu sind, werden dafür sorgen, dass die Insignien zu unseren Verbündeten draußen gelangen. Ihr seid wirklich sehr nützlich." }
quests[84287] = { id = 84287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Inschriftenkunde", description = "Ihr versteht Euch also auf Inschriftenkunde? Ich kenne eine der besten Schreiberinnen in Dornogal.\n\nIhr solltet nach Brrigan auf der Südseite der Schmiedegründe Ausschau halten.\n\nBrrigan hat einen Zeichentisch, an dem Ihr Arbeitsaufträge aus öffentlichen Listen und persönlichen Kontakten wie Freunden und Gildenkollegen prüfen, herstellen und ausliefern könnt. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet. Davon habe ich jedenfalls gehört.", sourceObjective = "Sucht Brrigan in den Schmiedegründen auf und verwendet ihren Zeichentisch.", completion = "Ich konnte viel aus unserer Interaktion lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84288] = { id = 84288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksaufträge: Alchemie", description = "Ihr versteht Euch also auf Alchemie? Ich verstehe.\n\nIhr solltet Tarig besuchen. Sie ist eine gute Alchemistin.\n\nTarig hat einen Alchemielabortisch im südlichen Teil der Schmiedegründe. Dort kann sie Euch helfen, Arbeitsaufträge aus öffentlichen Listen und von persönlichen Kontakten wie Freunden und Gildenkollegen zu überprüfen, auszuführen und auszuliefern. Wenn Ihr Glück habt, stoßt Ihr vielleicht auf einen Auftrag eines angesehenen Kunden, der zusätzliche Belohnungen bietet.", sourceObjective = "Sucht Tarig in den Schmiedegründen auf und verwendet ihren Labortisch des Alchemisten.", progress = "Ich würde es mir nie entgehen lassen, meine Expertise zu teilen... oder meinen Labortisch!", completion = "Es ist immer eine Ehre, einen anderen Alchemisten zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84296] = { id = 84296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur ist kalt geworden", description = "Ich habe die Fährte von Schrapp bis hierher verfolgt, aber in dieser kalten Luft hat sie sich aufgelöst. Dafür habe ich ein paar zerrissene Zettel gefunden. Noch habe ich auf ihnen nichts Nützliches gesehen, aber in seiner Eile hat er so wohl unabsichtlich eine Spur gelegt.\n\nAchtet auf Hinweise, die uns zum Versteck unseres Schurken führen könnten. Ich werde meine Fundstellen auf Eurer Karte markieren.\n\nNehmt die Geisterschwinges Pfeife und ruft uns, wenn Ihr Hilfe braucht.", sourceObjective = "Findet Schrapps Versteck.", completion = "Ein Gestaltwandler? Oh, das ist ganz schlecht.\n\nWir sollten den Detektiv warnen. Allerdings habe ich ihn in letzter Zeit nicht gesehen.\n\nKommt morgen wieder. Dann ist er bestimmt zurückgekehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84298] = { id = 84298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AUSHILFE GESUCHT: Kaja'Kuriositäten", description = "<Dieser Aushang ist neu und stammt vom Bilgewasserkartell.>\n\nIhr mögt Kaja'mit? Ihr sucht eine intellektuelle Herausforderung unter der tropischen Sonne? Ihr wollt hochmoderne Werkzeuge entwickeln, die nur explodieren, wenn sie auch sollen? Springt auf einen Raketenbohrer zur Kaja'Küste!\n\nKeine Erfahrung erforderlich. Kampffertigkeiten sehr willkommen. Auftragnehmer haften für ihre eigene Sicherheit. Vergütung und Arbeitsstunden werden vor Ort verhandelt.\n\nFür mehr Informationen sucht Jazz Mokkitz an der Kaja'Küste auf.", sourceObjective = "Sprecht mit Jazz Mokkitz an der Kaja'Küste.", progress = "Recherche erfordert Herz, sicher, aber ich würde meins gern behalten.", completion = "<Jazz klopft sich den Staub ab. Er wirkt erschöpft.>\n\nIhr würdet nicht glauben, wie oft mir das heute schon passiert ist - diesmal war es aber am Heftigsten.\n\n Hoffentlich seid Ihr bereit, Euch die Hände schmutzig zu machen, {name}. Wir haben zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[84299] = { id = 84299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piratenbeute", description = "Wir haben hier eine gute Sache am Laufen, aber diese Piraten sind schlecht fürs Geschäft! Die klau'n all unsere besonderen Edelsteine und haben sich sogar mit unserem Kaja'Cola-Vorrat aus dem Staub gemacht!\n\nEntledigt Euch dieses Lumpenpacks und bringt uns zurück, was sie gestohl'n haben!", sourceObjective = "Bilgerattentruppen gestört", completion = "Gut und effizient! Ich wusste, dass ich mich auf Euch verlassen kann, um meinen Profit zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[84300] = { id = 84300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veredeln, reparieren, von vorn.", description = "<Jazz hält einen gut polierten Kaja'mit-Kristall hoch.>\n\nDie meisten Materialien kann man nicht direkt nach dem Abbau nutzen, auch Kaja'mit nicht. Ich habe einige veredelte Kristalle, mit denen ich arbeiten kann, aber ich brauche mehr.\n\nIch habe einige Veredler auf den Hängen aufgestellt, aber auf halber Strecke haben die Elementare angefangen, ziemlich übel draufzuhauen.\n\nWürdet Ihr nachsehen, ob Ihr sie wieder zum Laufen bringen könnt? Ihr seht aus, als könntet Ihr es mit diesen wütenden Steinen aufnehmen. Und meine Frau hat es lieber, wenn ich unverletzt nach Hause komme.", sourceObjective = "Repariert 6 kaputte Kaja'mitveredler an der Kaja'Küste.", progress = "Waren sie noch zu retten? Ich musste sie für diesen Auftrag extra bauen.", completion = "Ich war mit nicht sicher, wie sich diese Veredler unter Stress halten würden. Ich bin froh, dass Ihr sie repariert habt! \n\n<Jazz spielt beiläufig mit einem kleinen Kaja'mitkristall.>\n\nGlaubt Ihr, ich könnte ein Patent auf die Baupläne anmelden? Mit den Lizenzgebühren könnte ich ausgesorgt haben, wenn ich genug verlange.", sourceObjectiveStatus = "unverified-source-field" }
quests[84301] = { id = 84301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mineralienwahnsinn", description = "Mit all diesen Elementaren, die Verwüstung verursachen, ist es unmöglich, hier zu arbeiten! Wie sollen wir bitte Rohmaterialien sammeln, wenn sie damit nach uns werfen?\n\n<Jazz verstummt und seine Augen leuchten auf.>\n\n{name}, diese Elementare SIND unsere Rohmaterialien. Sie zu verkloppen ist unsere beste Chance - obwohl Ihr das für mich machen müsstet.\n\nAlso, nicht einschlafen! Zeit ist Geld und ich bin niemand, der gerne Forschungsgelder verschwendet.", sourceObjective = "Merzt aggressive Kaja'mitelementare aus und sammelt 12 Klumpen rohes Kaja'mit.", progress = "Wer hätte gedacht, dass dieser Ort so viel elementare Aktivität zeigen würde! Kein Wunder, dass die Düsternisverschmolzenen alle Hände voll zu tun hatten.", completion = "Ich werde einige Schamanen herholen müssen, um die restlichen Steine zu beruhigen. \n\nSie können nichts dafür, dass sie wütend sind, aber der Berg ist schon gesprengt. Daran können wir nichts mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[84302] = { id = 84302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreative Iteration", description = "Gut, {name}, jetzt wird es ernst. Ihr habt die Kristalle und ich habe alle Teile für meine Arbeit!\n\nKaja'mit ist gut geeignet, um flüchtige Energien zu speichern. Ich glaube, wir können daraus etwas besseres machen als die Waffen der Düsternisverschmolzenen, aber zuerst brauchen wir ein Versuchsobjekt.\n\nIch habe da diesen alten, fehlerhaften Schrottschrumpfstrahl. Das Kaja'mit sollte ihn stabilisieren. Wenn es das tut, stehen wir womöglich vor einem Durchbruch!\n\nIch brauche ein zweites Paar Hände, um an diesem Ding zu basteln. Befolgt einfach meine Anweisungen, dann bleibt Ihr in einem Stück. Vielleicht.", sourceObjective = "Helft Jazz bei seiner Tüfetelei mit dem Schrumpfstrahl und dem Kaja'mit.", completion = "Nun, wir sind beide unversehrt. Der Schrumpfstrahl ist nicht zerstört. Das nenne ich mal einen vollen Erfolg!\n\nStellt Euch nur vor, {name}, wie effizient man mit diesem Schrumpfstrahl Vorräte in ein Fahrzeug packen könnte. Wir könnten mehr Leute auf demselben Raum transportieren! Ich kann es kaum erwarten, das meiner Frau zu erzählen!\n\n\n\nVerzeiht, ich habe mich mitreißen lassen. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84303] = { id = 84303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentelle Anwendung", description = "<Jazz drückt Euch den Schrumpfstrahl in die Hand.>\n\nNun müssen wir nur noch den Prototyp testen, {name}. Probiert ihn an den Elementaren aus! Wenn er bei denen funktioniert, funktioniert er bei allem... vermutlich.\n\nErwartet aber nicht, dass der Effekt lange anhält. Das ist nur die erste Iteration. Und bleibt in den Minen. Nur, falls wir irgendwelche Probleme begraben müssen.\n\nSeht mich nicht so an. Ich habe ihn ursprünglich gebaut, um meiner Frau die Angst vor Spinnen zu nehmen. Ich schwöre, es gibt mindestens EINE funktionierende Notsicherung.", sourceObjective = "Testet das Kaja'Eindämmungsgerät an 8 Kaja'mitkrabblern in den Glücksmomentminen.", completion = "Ich wusste, Ihr schafft das! Perfekt sicher in der Anwendung.\n \n<Jazz räuspert sich.>\n \nIch werde Euch in jedem Patent, das ich anmelde, erwähnen. Versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84304] = { id = 84304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Split", description = "He, {name}! Rache ist sonst nicht mein Ding, aber ich habe eine Idee. \n\nDieser große Kerl, der uns rumgeschubst hat, ist da lang gelaufen. Ich wette, er ist irgendwo in den Minen. Und ich wette, wir können eine riesige Probe von seinem Körper nehmen. Das würde mir meine zukünftigen Tüfteleien deutlich erleichtern.\n\nAußerdem kommt er nicht wieder, wenn wir ihn ausschalten, und ich würde diesen Job gerne unversehrt abschließen. Ich habe Rechnungen zu bezahlen und Kinder zu ernähren! \n\nProbiert den Schrumpfstrahl an diesem Brocken aus. Zeigt ihm, wer der Boss ist! Für die Wissenschaft, natürlich.", sourceObjective = "Nutzt den Prototyp, um den wütenden Kaja'mit-Juwelensplitter zu schwächen und zu töten.", progress = "Gut, Euch wohlauf zu sehen. Wie lief es?", completion = "Ich schulde Euch was, Kumpel. Wir sind definitiv im Geschäft, wenn unser kleiner Prototyp dieses Riesending einige Köpfe kürzer machen konnte!\n\nIch werde ein größeres Team hier draußen brauchen, um weiterzutüfteln. Aus Kaja'mit lässt sich auf jeden Fall mehr machen als Waffen oder Kaltgetränke, das sag ich Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[84305] = { id = 84305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen in Khaz Algar, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
