quests[84334] = { id = 84334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt den Detektiv", description = "Willkommen zurück, {name}.\n\nIch habe gesehen, wie der Detektiv nach Westen gegangen ist. Beeilt Euch und warnt ihn, bevor der Gestaltwandler ihn ebenfalls holt!", sourceObjective = "Warnt Detektiv Jones vor dem Gestaltwandler.", completion = "Ein Gestaltwandler? Ha! Mumpitz!", sourceObjectiveStatus = "unverified-source-field" }
quests[84336] = { id = 84336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Unterschied", description = "Hört mal, ich bin der echte Detektiv. Ihr glaubt mir doch, oder?\n\nIch weiß... Fragt mich irgendetwas. Die netten Leute hier werden meine Geschichte bestätigen, und wir werden beweisen, dass ich ich bin.", sourceObjective = "Löst den Fall des gestaltwandelnden Dämons.", completion = "Vielen Dank, dass Ihr den Fall gelöst habt, {name}!\n\nHoffentlich läuft diese Veranstaltung jetzt ruhiger ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[84352] = { id = 84352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Herumgelaufe mehr", description = "Wir müssen etwas dagegen tun, dass Ihr so lange braucht, von A nach B zu kommen. Zum Glück kenne ich genau die Richtige. Trefft Euch mit Omi Talullah in der Caddie-Hütte und fragt sie, ob sie Euch einen fahrbaren Untersatz leihen kann.", sourceObjective = "Trefft Omi Talullah im zweiten Stock der Caddie-Hütte.", completion = "Ihr braucht ein Auto? Natürlich haben wir ein Auto für Euch! Wir haben so viele Autos! Hier, ich habe sogar ein paar Ersatzschlüssel dabei!", sourceObjectiveStatus = "unverified-source-field" }
quests[84363] = { id = 84363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szatszszuche", description = "Ichz weisz! Wir könnten den Sztock nutszen, um nach Szätszen zu suchen!\n\nIhr und Enzo szucht bei den anderen Ruinen. Findet wasz richztig Coolesz!\n\nWir szehen unsz dann auf der Party.", sourceObjective = "Nutzt die Fackel von Pyrreth, um nach Schätzen nahe den Ruinen von Tanaris zu suchen.", completion = "Wow, tasz iszt doch mal ein Szatsz!", sourceObjectiveStatus = "unverified-source-field" }
quests[84365] = { id = 84365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas zieht auf", description = "Branns Späher haben Verstärkung gesichtet, die sich der Küste von Khaz Algar nähert.\n\n Er hat die Abenteurer dazu aufgerufen, sich ihm in Dornogal anzuschließen.", sourceObjective = "Sprecht mit Brann Bronzebart in Dornogal.", completion = "Ich habe gehört, dass sich Verstärkung der Insel nähert. Ihr kennt Khaz Algar in- und auswendig. Sie werden euer Wissen brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84367] = { id = 84367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für eine Zusammenkunft", description = "Wir sollten bald eine ganze Flotte Verstärkung bekommen. Gerade rechtzeitig. Ich habe gehört, dass Alleria und Anduin wieder in Dornogal sind.\n\nWie ich Moira kenne, arbeitet sie bereits mit ihnen zusammen und plant unseren nächsten Schritt. Sie versteht das Anführen, wie ein Greifen das Fliegen versteht. Am besten, Ihr sucht sie auf, bevor sie Euch aufsucht.", sourceObjective = "Sprecht mit Moira Thaurissan in Dornogal.", completion = "Genau zur richtigen Zeit. Zum ersten Mal, seit wir hier abgestürzt sind, habe ich gute Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84370] = { id = 84370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zum Erfolg", description = "<Ein Chiffrenschlüssel? Elise Sternensucher weiß vielleicht, was man damit machen kann.>", sourceObjective = "Bringt den archaischen Chiffrenschlüssel zu Elise Sternensucher in Dornogal.", progress = "Diese Karte ergibt keinen Sinn... Champion! Ich hoffe, es gibt gute Nachrichten?", completion = "Erstaunlich! Das ist es, was ich übersehen habe. \n\nDie Karte, die Finley gefunden hat, ist chiffriert. Aber dieser Schlüssel ist unvollständig... Wenn Ihr da draußen noch mehr findet, bringt sie bitte zu mir. Ich werde diese Karte entschlüsseln, so wahr ich Elise Sternensucher heiße.", sourceObjectiveStatus = "unverified-source-field" }
quests[84371] = { id = 84371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Die Klinge und der Hohepriester", description = "Xal'atath, die Vorbotin der Leere, ist eine gefährliche und listige Feindin. Sie war vorsichtig und hat nur einige wenige ihre Anwesenheit vernehmen lassen.\n\nZum ersten Mal haben wir während der dritten Invasion der Legion auf Azeroth von ihr gehört, doch es wird gemunkelt, dass sie schon deutlich früher zugegen war.\n\nEs handelt sich hierbei um eine Geschichte um Macht, Dunkelheit und Täuschung. Gesellt Euch zu mir und ich erzähle Euch die Geschichte hinter Xal'ataths geheimnisvoller Vergangenheit.", sourceObjective = "Folgt Chos Weisung, um mehr über die Geschichte hinter Xal'ataths Vergangenheit zu erfahren.", completion = "Xal'atath war eine mächtige Waffe und... gesprächige Präsenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[84376] = { id = 84376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgewerteter Besitz", description = "<Ihr kommt an einem Plakat vorbei, das über ein \"Zu vermieten\"-Schild genagelt wurde.>\n\nGESUCHT: Suche tüchtige Abenteurer für Sicherheitsarbeit in örtlichem Wohnblock.\n\nMuss in der Lage sein, nicht zu sterben.\n\nBELOHNUNG: Kostenlose Unterkunft und Verpflegung für die geleisteten Dienste.\n\nInteressenten sollten sich im obersten Stockwerk der Fassgrundwohnungen nach weiteren Einzelheiten erkundigen.", sourceObjective = "Besucht die Fassgrund-Apartments und fragt nach einem freien Zimmer.", progress = "Dieser Moz macht mich verrückt! Vielleicht könnt Ihr ihn zur Vernunft bringen.", completion = "Ich hätte nicht gedacht, dass tatsächlich jemand auftaucht. Seid Ihr wegen des Zimmers hier?\n\nIhr habt Fassgrund doch nichts gesagt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[84378] = { id = 84378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mieterversicherung", description = "Schlimm genug, dass der knauserige Vermieter die Bude hier verfallen lässt, aber jetzt haben wir noch größere Probleme.\n\nZuletzt sind diese Möchtegernganoven die Straße hoch, Tiefenreiter oder wie sie sich nennen, von Taschendiebstahl und Lärmbelästigung zu einer schwer bewaffneten Plage aufgestiegen. Die zerdeppern hier alles und greifen uns sogar direkt an!\n\nUnd wer es sich nicht leisten kann, wegzuziehen, wird stattdessen zwangsgeräumt wegen der Schäden, die diese Rüpel verursachen.\n\nWenn Ihr uns beschützt, könnt Ihr hier kostenlos nächtigen.", sourceObjective = "Tötet 12 Mitglieder der Tiefenreiter-Rockerbande.", completion = "Ihr seid zurück.\n\n<Keara zuckt vor Schmerz zusammen.>\n\nAn Eurem Timing können wir noch etwas arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84379] = { id = 84379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mietnomaden", description = "<Gabi winkt Euch dringend herbei.\n\nDie kleine Goblindame knetet nervös die Hände und sucht nach den richtigen Worten, um ihr Anliegen zu erklären.>\n\nEinige Goblins ziehen nicht aus... sie werden entführt. Ich weiß es ganz sicher.\n\nMeine Freunde würden dem Ort hier nicht einfach den Rücken kehren. Niemals.\n\n<Gabi sieht Euch mit tränennassen Augen flehend an.>\n\nBitte helft ihnen, {class}. Ja?", sourceObjective = "Rettet 8 gefangene Mieter.", completion = "Alle gerettet. Nur, um wieder angegriffen zu werden.\n\nDas können wir so nicht stehen lassen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84380] = { id = 84380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffentruhe", description = "<In der Waffentruhe findet Ihr eine zerknüllte Notiz der Tiefenreiter.>\n\nSchön zu sehen, dass Ihr Euer neues Spielzeug gut einzusetzen wisst. Dank Euch machen sich diese kleinen Hausbesetzer in Scharen davon!\n\nMacht weiter so und es wartet noch mehr davon auf Euch. Passt nur auf, dass Ihr nicht alles niederbrennt. Ich kann ja schlecht ein leeres Grundstück vermieten, haha!\n\nGezeichnet\nM. F.G.", sourceObjective = "Zerstört Ausrüstung der Tiefenreiter in ihrem Unterschlupf.", progress = "Habt Ihr was gefunden?", completion = "Ein Brief von den Tiefenreitern? Oh, ich glaube, ich erkenne diese Unterschrift...\n\nDie ist von dem schleimigen Vermieter Moz Fassgrund!", sourceObjectiveStatus = "unverified-source-field" }
quests[84381] = { id = 84381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuverhandlungen", description = "Damit ist die Sache klar! Ich glaube, wir wissen beide, wer für das Chaos verantwortlich ist. Dahinter steckt dieser verdammte Vermieter Moz Fassgrund!\n\nKaum waren die Tiefenreiter aus dem Verkehr gezogen, hat er seinen Schläger Jarvis auf uns gehetzt. Nachdem es nicht geklappt hat, uns zu verscheuchen, versucht er jetzt, uns mit aller Gewalt zu vertreiben.\n\n<Keara spuckt verächtlich auf den Boden.>\n\nAber so leicht macht er uns keine Angst.\n\nIhr seid ziemlich zäh, {name}. Moz hat sein Büro gleich gegenüber. Na los, zeigt ihm, dass er sich mit den falschen Goblins angelegt hat!", sourceObjective = "Besiegt Jarvis Knochenbrecher und erlangt die Fassgrundurkunde von Moz Fassgrund in seinem Büro im dritten Stock gegenüber.", progress = "Wir kommen schon zurecht. Kümmert Ihr Euch bloß um Moz!", completion = "Hah! Damit lernt der alte Geizkragen, wer hier das Sagen hat. Und dank dieser Urkunde kann er uns mit nix drohen!\n\nIhr habt ganze Arbeit geleistet. Das Gratiszimmer habt Ihr Euch redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[84392] = { id = 84392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Hunger im Grollwinkel", description = "Hey, seid Ihr auf der Suche nach einer köstlichen Mahlzeit?\n\nWürdet Ihr dafür durch den Schlamm waten?\n\nGeht zu Dolena. Sie wird Euch weiterhelfen. Macht Euch aber nicht die Mühe, sie zu überreden, den Grollwinkel zu verlassen. Glaubt mir, wir haben es alle versucht. Warum jemand die Sicherheit des Lichts für so etwas verlässt...\n\nSie scheint aber gut zurechtzukommen.", sourceObjective = "Sucht Dolena im Grollwinkel auf", completion = "Ah, noch jemand. Seid Ihr absichtlich hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[84393] = { id = 84393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ter Sztock ter Offenbawung", description = "Szo, esz wird Szeit, ten Sztock ter Offenbawung zu nutszen!\n\nFolgt mir.", sourceObjective = "Folgt Maru und entzündet die Feuerschale vor den Ruinen von Uldum mit der Fackel von Pyrreth.", progress = "Ein guter Sznüffler weisz, wie man all dasz Szeug benutszt.", completion = "Sooo coooool!", sourceObjectiveStatus = "unverified-source-field" }
quests[84403] = { id = 84403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Bündel voller Waren", sourceObjective = "Aufgabe abgeschlossen. Der Rat belohnt Euch für Eure Hilfe bei der Wiedervereinigung der Irdenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84404] = { id = 84404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Bündel voller Waren", sourceObjective = "Aufgabe abgeschlossen. Der Rat belohnt Euch für Eure Hilfe bei der Wiedervereinigung der Irdenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84409] = { id = 84409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Tapferen", sourceObjective = "Die Arathi wissen Eure Hilfe in diesen gefährlichen Landen wirklich zu schätzen. Nehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[84419] = { id = 84419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf szu den Ruinen!", description = "Ihr habt dasz Sznüffel-Tingszda von meinem Bwuder gefunden!\n\n<Maru hält es ehrfürchtig hoch.>\n\nTer Sztock ter Offenbawung! Tasz Ting kann Lichzter anmachen, Szeug szmelszen und szogar ALTE SZÄTSZE öffnen. Dafür musz man es einfach hochhalten!\n\nWir wollten ihn an tiesem Ting vor ten Ruinen von Uldum auszprobieren. Kommt Ihr mit?", sourceObjective = "Trefft Maru und Enzo vor den Ruinen von Uldum.", completion = "Beweit für ein Abenteuwer?", sourceObjectiveStatus = "unverified-source-field" }
quests[84423] = { id = 84423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Staub abschütteln", description = "Wow, Ihr seht wirklich stark aus. Könntet Ihr mir vielleicht helfen?\n\nMeine Eltern wurden von den gemeinen Kobyss getötet. Als ich hierhin geflohen bin, musste ich meinen geliebten Teddybären zurücklassen.\n\nKönntet Ihr ihn für mich holen?", sourceObjective = "Holt Alyzas vielgeliebten Teddybär aus dem Lauernden Strudel in Heilsturz.", completion = "Willkommen zurück im Land der Lebenden, {class}. \n\nIhr habt viel nachzuholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84424] = { id = 84424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts ins Abenteuer!", description = "Wir sind frei, {class}. Frei, zu tun, was auch immer wir wollen.\n\nHinter dem Portal liegt der Rest Eures Lebens.\n\nEin Mitglied des bronzenen Drachenschwarms wird Euch auf Eurer Reise helfen.", sourceObjective = "Durchschreitet das Portal im Kriegshort, um zu Chromie zu gelangen.", completion = "Zeit, Euch auf den neuesten Stand zu bringen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[84426] = { id = 84426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässte Feierkiste", description = "<Die Kiste ist pitschnass, aber das Innere sollte nichts abbekommen haben. Alyx würde sich über die Vorräte freuen.>", sourceObjective = "Bringt die durchnässte Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84429] = { id = 84429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstrukteindämmung" }
quests[84430] = { id = 84430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkreuzzug", description = "Ich habe geschworen, Beledar mit meinem Leben zu beschützen, und jetzt singt ein neuer Stern vom Meer her für uns.\n\nIch weiß nicht, was das für die Arathi bedeutet, aber es führt wahrscheinlich zu Unheil, wenn wir zulassen, dass diese üblen Kreaturen der Tiefe Teile davon an sich reißen.\n\nTötet sie mit äußerster Vorsicht und sammelt alle Teile des Kristalls in ihrem Besitz ein.", sourceObjective = "Holt 10 Kristallfragmente und 30 Kristallbrocken von den Streitkräften der Naga zurück.", progress = "Habt Ihr die Kristallfragmente beschaffen können?", completion = "Möge Beledars Volk nun gedeihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84432] = { id = 84432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langschifflandung", description = "Diese Vrykul der Blutgischt nehmen keine Rücksicht auf uns und unsere Forschung. Selbst als wir versucht haben, unsere Entdeckungen mit ihnen zu teilen, wurden wir angegriffen!\n\nEs ist ihnen egal, dass wir der Insel nichts Böses wollen. Sie wollen, dass wir verschwinden.\n\nAber wir können jetzt nicht gehen. Es gibt noch so viel mehr zu entdecken! Jemand muss ihnen verständlich machen, dass wir noch nicht gehen und sie uns in Ruhe lassen sollen.\n\nWir müssen ihnen zeigen, dass wir uns wehren werden.", sourceObjective = "Eliminiert 15 Vrykul der Blutgischt.", completion = "Ich bin kein Freund von Gewalt als Lösung, aber manchmal ist Gewalt die einzige Option.", sourceObjectiveStatus = "unverified-source-field" }
quests[84435] = { id = 84435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nolas letzter Wunsch", description = "Grüße, {name}! Könntet Ihr mal nach Lashk sehen?\n\nEr scheint wegen irgendetwas aufgebracht zu sein.", sourceObjective = "Löst Lashks Rätsel.", progress = "Die Geschichten, die Nola erzählen könnte...", completion = "Es beruhigt mich, zu wissen, dass sie jetzt in Frieden ruht.\n\nIch werde diese Geschichte noch viele Jahre lang erzählen, {name}. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[84438] = { id = 84438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichter Sieg", sourceObjective = "Das Glück begünstigt die Mutigen... und jene, die gut mit Karten umgehen können. Unser Freund Millhaus war wenig erfreut, sich von dieser Schriftrolle zu trennen, genauso wenig wie von all seinen anderen Besitztümern.\n\nNehmt sie, {race}. Das ist das Mindeste, was ich angesichts dessen tun kann, was Ihr für die Überlebenden von Dalaran getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84439] = { id = 84439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Fazit", description = "Ihr habt mir hier wirklich ausgeholfen, {name}, aber ich muss Euch um noch einen winzig kleinen Gefallen bitten.\n\n<Jazz reicht Euch einen Umschlag, der mit Plänen und schriftlichen Berichten vollgestopft ist.>\n\nKönntet Ihr das zu meinem Agenten, Kory Hoxx bringen? Er bringt es dann ins Hauptquartier. Ihr findet ihn wahrscheinlich im Hotel Inkontinental, wo er weitere Auftragsblätter aufhängt.", sourceObjective = "Bringt Jazz' Bericht zu Kory Hoxx im Hotel Inkontinental.", progress = "Seht Ihr nicht, dass ich beschäftigt bin? Personalbeschaffung ist harte Arbeit, wisst Ihr?", completion = "Oh, Jazz hat Neuigkeiten? Warum sagt Ihr das nicht gleich!\n\n<Kory schnappt sich den Umschlag, reißt ihn auf und liest den Bericht.>\n\nEr braucht WIE VIELE Leute?!", sourceObjectiveStatus = "unverified-source-field" }
quests[84442] = { id = 84442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung zum Geisterfest", sourceObjective = "Trefft Aysa Wolkensänger in Sturmwind, in der Nähe des Heißluftballons.", completion = "Ihr habt es geschafft!\n\nWas die Reise zur Wandernden Insel angeht... seid Ihr bereit für eine Heißluftballonfahrt?", sourceObjectiveStatus = "unverified-source-field" }
quests[84446] = { id = 84446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm Khaz Algars", description = "Wir haben noch viel zu tun, um Khaz Algar zu helfen.\n\nAber ich weiß nicht viel über dieses Land jenseits der Reiche der Irdenen.\n\nIch muss Euch an Faerin Lothar verweisen, um zu sehen, was Heilsturz brauchen könnte.\n\nSprecht mit ihr und fragt, ob sie Hilfe braucht. Ihr kennt Euch doch bereits, oder?", sourceObjective = "Sprecht mit Faerin Lothar in Dornogal.", completion = "Schön, Euch wiederzusehen, {name}.\n\nWir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[84451] = { id = 84451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wanderer", sourceObjective = "Reist mit dem Heißluftballon zur Wandernden Insel.", completion = "Es ist toll, Papa wiederzusehen!\n\nAber... was ist aus all den Festlichkeiten geworden? Warum wirkt er so besorgt?", sourceObjectiveStatus = "unverified-source-field" }
quests[84453] = { id = 84453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Dai-Lo-Bauernhof", description = "Mein Bruder Chon Po hat versucht, alle zu versammeln. Er hat handgeschriebene Einladungen an jedes Dorf geschickt. Könnt Ihr das glauben? Er ist ein Braumeister. Er hätte Gebräu schicken sollen!\n\nDer Dai-Lo-Bauernhof war wie ein zweites Zuhause für uns. Chon Po und ich haben die Hälfte unserer Kindheit dort verbracht, haben bei der Ernte geholfen. Dort haben wir unser erstes Bier gebraut.\n\nVerabreichen wir den Dorfbewohnern von Dai-Lo eine ordentliche Dosis Nostalgie, und auch etwas Neues, als Vorgeschmack auf das kommende Fest.", sourceObjective = "Reist zum Dai-Lo-Bauernhof auf der Wandernden Insel.", completion = "Gute Nachrichten! Einige haben sich bereits auf das Fest vorbereitet, also müssen wir nicht das ganze Dorf überzeugen!\n\nSchlechte Nachrichten: Es gibt ein großes Problem auf den Feldern. Die Shed-Ling treiben wieder ihr Unwesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84454] = { id = 84454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shed-Ling-Flut", description = "Ich hatte bei unserer Ankunft auf eine herzlichere Begrüßung gehofft. Leider sind viele Dorfbewohner auf den Feldern beschäftigt. Die Ernte ist in vollem Gange, und die Shed-Ling sind es auch.\n\nWir haben diese Plage mein ganzes Leben lang bekämpft. Ich weiß nicht, wie sie es schaffen, immer wiederzukommen!\n\nChon Po und ich bereiten gerade die Bierverkostung vor. Könnt Ihr Euch um die Probleme auf den Feldern kümmern?", sourceObjective = "Erobert die Ränge zurück, indem Ihr Shed-Ling tötet, Erntegut sammelt und den Bauern helft.", completion = "Die Shed-Ling werden zweifelsohne zurückkehren, aber jetzt können wir feiern.\n\nWir bringen etwas von der frischen Ernte zum Fest.", sourceObjectiveStatus = "unverified-source-field" }
quests[84455] = { id = 84455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dicke Bertha", description = "Ich liebe Chens Idee, die Dorfbewohner mit einer Bierverkostung zu locken. Ich bin überrascht, dass ich nicht selbst darauf gekommen bin!\n\nMeine Freunde hatten gehofft, einen großen Teil der Ernte zum Fest zu bringen. Aber die Dicke Bertha ist verschwunden! Wir brauchen sie, wenn wir all die Speisen und Getränke rechtzeitig heimbringen wollen.\n\nDie Dorfbewohner sagen, sie hätte sich plötzlich von ihrem Wagen losgerissen und sei unter die Erde verschwunden.\n\nIch mache mir Sorgen. Sie mag groß sein, aber sie hat ein weiches Herz. Könnt Ihr sie finden?", sourceObjective = "Findet und rettet die Dicke Bertha in den Rängen.", completion = "Wenn es hart auf hart gekommen wäre, hätte die Dicke Bertha diese Shed-Ling bestimmt zertrampelt. Aber ich bin froh, dass Ihr ihr diesen Stress erspart habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84457] = { id = 84457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Morgenhauch", description = "Chon Po hat gesagt, er hätte mehrere Einladungen an die Dorfbewohner von Morgenhauch geschickt, aber niemand ist erschienen.\n\nDas ist seltsam. Normalerweise freuen sie sich am meisten auf das Geisterfest. Jede Gelegenheit, Feuerwerkskörper herzustellen und zu zünden, ist ihnen recht!\n\nIrgendetwas muss geschehen sein. Finden wir es heraus.", sourceObjective = "Reist nach Morgenhauch auf der Wandernden Insel.", completion = "Das erklärt alles. Ihre Feuerwerkskörper sind verschwunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[84458] = { id = 84458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teufel steckt im Detail", description = "Suchen wir im Dorf nach verdächtigen Spuren. Ich glaube nicht, dass die Feuerwerkskörper einfach verlegt wurden. Shisai ist ein wachsamer Pandaren, und das ist sein großer Beitrag zum Fest.\n\nDer Diebstahl muss vor Kurzem geschehen sein. Jemand muss etwas gesehen haben.", sourceObjective = "Sucht 3 Hinweise zu den verschwundenen Feuerwerkskörpern in Morgenhauch.", completion = "Der Fall ist klarer, als ich gedacht habe. Alles deutet auf den Ho-zen hin!", sourceObjectiveStatus = "unverified-source-field" }
quests[84459] = { id = 84459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strolche sind's nicht!", description = "Shisai hat gesagt, die Feuerwerkskörper wären in einem Fass...\n\n<Ji fährt sich mit der Tatze über das Gesicht.>\n\nUnd... er hat sie wahrscheinlich ins falsche Fass gelegt. Bei all den Vorbereitungen fürs Fest wäre es ein Wunder, wenn keine Waren vertauscht worden wären.\n\nNa gut, durchsuchen wir die Fässer! Es wird nicht lange dauern.", sourceObjective = "Durchsucht 8 Holzfässer in Morgenhauch.", progress = "Das sind wirklich eine Menge Fässer...", completion = "Hm... keine Feuerwerkskörper in diesen Fässern. Es gibt noch mehr Fässer im Dorf... aber wie groß ist die Wahrscheinlichkeit, dass wir fündig werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[84460] = { id = 84460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertappt oder im Dunkeln getappt?", description = "Alle Hinweise deuten darauf hin, dass die Ho-zen die Feuerwerkskörper gestohlen haben! Es ist, wie Ji gesagt hat: Sie haben es schon einmal getan, und sie werden es wieder tun.\n\nStellen wir sie sofort.", sourceObjective = "Stellt Huk Huk, den Häuptling der Ho-zen, in Fe-Feng.", completion = "Oh!\n\n<Aysa errötet.>\n\nDas ist auf jeden Fall unerwartet. Ich bin angenehm überrascht.", sourceObjectiveStatus = "unverified-source-field" }
quests[84461] = { id = 84461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Geister kein Geisterfest", description = "<Der Kranich trägt einen Brief. Er ist von Li Li.>\n\nIrgendetwas stimmt im Tempel der Fünf Sonnenaufgänge nicht. Ich brauche Eure Hilfe. Bitte kommt, so schnell Ihr könnt!", sourceObjective = "Trefft Li Li Sturmbräu im Tempel der Fünf Sonnenaufgänge.", completion = "Ich bin froh, dass Ihr schnell gekommen seid, {name}! Auf Herr Kranich ist eben einfach Verlass. Er überbringt Botschaften so schnell wie der Wind.\n\nApropos Wind...", sourceObjectiveStatus = "unverified-source-field" }
quests[84462] = { id = 84462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muster im Rauschen", description = "Ich kann keine der Geister im Tempel finden. Wie sollen wir ein Geisterfest ohne Geister feiern?\n\nDer heutige Tag ist eine Feier aller vier Elementargeister, doch vielleicht ist es für sie nur ein ganz gewöhnlicher Tag. Wir müssen sie finden und es ihnen erzählen!\n\nSchaut, ist das die Spur des Windgeistes? Vielleicht führt sie uns zu Dafeng... der uns zu den anderen führen kann.", sourceObjective = "Sammelt 30 Überreste des Windes und nutzt ihre Macht, um Dafeng im Tempel der Fünf Sonnenaufgänge zu finden.", progress = "<Dafeng schwebt und wartet auf etwas.>", completion = "<Dafeng dreht sich begeistert im Kreis, kommt aber schnell zum Stillstand. Er scheint nach den anderen Geistern zu suchen. Vielleicht braucht er Hilfe?>", sourceObjectiveStatus = "unverified-source-field" }
quests[84463] = { id = 84463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Schlammassel", sourceObjective = "Befreit Shu und Wugou, indem Ihr die Schlammverschmelzung im Pei-Wu-Wald besiegt.", completion = "Ihr und Jojo habt es geschafft! Danke.\n\nHuo ist der letzte fehlende Geist. Warum hat mich Dafeng zu einem Teich geführt? Wasser und Feuer vertragen sich nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[84464] = { id = 84464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flackernde Flamme", description = "Dafeng hat mich hierhergeführt, aber dann ist er davongeflogen. Ich denke, er spürt die Nähe von Huo, dem Geist des Feuers.\n\nWarum sind alle Geister heute so aufgewühlt? Das Fest ist doch zu ihren Ehren. Und dann war da diese innere Stimme, die mich gedrängt hat, nach Hause zurückzukehren. Die Geister haben immer die Wahrheit über die Insel und ihre Pandaren widergespiegelt. Wenn sie aufgebracht sind, muss etwas nicht stimmen... oder etwas muss sich ändern.\n\n<Li Li seufzt und schüttelt den Kopf.>\n\nWir müssen erstmal Huo finden, und zwar schnell. Das muss seine Dunstspur sein.", sourceObjective = "Folgt der Dunstspur, um Huo, den uralten Geist des Feuers zu finden.", completion = "Huo ist wieder er selbst!\n\nIch hatte das Schlimmste befürchtet, als ich ihn hier gesehen habe. Ich hoffe, er weiß, dass wir ihn nicht vergessen haben und niemals im Stich lassen würden.\n\nDanke, {name}. Wir haben allen Geistern geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84465] = { id = 84465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Wasser und Blut", sourceObjective = "Sammelt 10 blaue Mohnblumen und tötet 10 Dornzweigstrolche im Stabwald.", progress = "Dieser Ort bringt so viele Erinnerungen zurück.", completion = "Ehrlich gesagt habe ich Papa mehr vermisst, als ich es mir eingestehen wollte. Es war schön, ihn wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84468] = { id = 84468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein echter Braudrauf", description = "Bereit für die Bierverkostung? Wir haben bereits die Aufmerksamkeit einer kleinen Menge erregt.\n\nIch habe etwas, das ihnen den Kopf verdrehen wird. Zutaten, von denen sie noch nie gehört haben, und eine perfektionierte Technik...\n\n<Chen platziert feierlich einen Gurkenstreifen auf einem Getränk.>", sourceObjective = "Verteilt Chens und Chon Pos hausgemachtes Bier an die Dorfbewohner.", progress = "<Chen beobachtet still die Reaktionen der Dorfbewohner.>", completion = "<Chen lächelt, trotz der zögerlichen Reaktionen der Dorfbewohner.>\n\nNeue Aromen brauchen Zeit, bis man sie zu schätzen weiß. Die Zitrusnote wird ihnen in Erinnerung bleiben... Was ist das genau? Eine süße Zitrone? Oder eine saure Melone? Es liegt in unserer Natur, das Unbekannte verstehen zu wollen.\n\nSie werden zurückkommen und mehr wollen, das weiß ich. Schließlich geht es beim Geisterfest darum, neue Abenteuer zu feiern!", sourceObjectiveStatus = "unverified-source-field" }
quests[84469] = { id = 84469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierbingo", description = "Hallo! Die Großmeistertierzähmer Pandarias haben eine Herausforderung ausgerufen, bei der man bestimmte Kampfhaustiere auf dieser kunstvollen Bingokarte finden soll.\n\nWir müssen nur das Haustier finden, das zum Rätsel passt, und es auf unsere Bingokarten schreiben. Die letzten beiden fallen mir aber ziemlich schwer. Normale Haustiere zu entdecken, ist ziemlich leicht, aber für diese Bingokarten müssen wir spezielle Versionen von ihnen finden.\n\nHmm... In den Regeln steht nichts darüber, dass man sich keine externe Hilfe holen darf. Möchtet Ihr einem Freund helfen?", sourceObjective = "Sucht die Kampfhaustiere, die durch die Rätsel beschrieben werden.", progress = "Habt Ihr ein Kampfhaustier gefunden?", completion = "Hey, vielen Dank!\n\nBINGO!", sourceObjectiveStatus = "unverified-source-field" }
quests[84470] = { id = 84470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckverkrustete Feierkiste", description = "<Die Kiste wurde freigelegt und entstaubt, riecht aber immer noch nach Tod. Trotzdem würde es Alyx sicher begrüßen, wenn sie die Vorräte zurückbekommt.>", sourceObjective = "Bringt die dreckverkrustete Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84489] = { id = 84489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaufrausch!", description = "Jetzt, wo Ihr ein Gefühl für die Hauptattraktionen habt, können wir über die Einkaufsmöglichkeiten reden.\n\nIm Hauptpavillon hier findet Ihr einige der Orte, an denen Ihr nach Herzenslust Euer Geld verprassen könnt. Lauft doch mal eine Runde und sprecht mit den Händlern, um zu sehen, was sie Euch anzubieten haben.\n\nKommt anschließend wieder zu mir zurück und lasst mich wissen, ob Euch etwas ins Auge gesprungen ist.\n\nTschüssi!", sourceObjective = "Sprecht mit den Händlern.", progress = "Zeigt bloß keine Scheu, Ihr dürft gerne stöbern. Na los, schaut Euch die Waren an und kommt anschließend wieder zurück.", completion = "Ich hoffe doch, dass Ihr etwas gefunden habt, das Euch gefällt. Oder dass Ihr zumindest etwas Spaß beim Stöbern hattet.\n\nIhr wisst jetzt, wie der Hase läuft, Ihr könnt nun also tun, wonach es Euch beliebt. Habt Spaß. Dieses Jubiläum ist schließlich für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[84490] = { id = 84490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Große Schatzkammer", description = "Viele der Systeme von Dornogal waren Jahrtausende lang inaktiv und sind jetzt wieder online. Eines davon, das Euch nützlich sein könnte, {race}, ist die Große Schatzkammer.\n\nEinst unterstützte dieses Versteck mit Rüstungen und Waffen die Irdenen bei ihrer eingeschworenen Pflicht, Dornogal zu schützen. Nun wird es Euch zur Verfügung gestellt in der Erwartung, dass Ihr das, was Ihr dort findet, nutzt, um anderen zu helfen.\n\nDie Schatzkammer befindet sich hier in Dornogal im Schatz des Rates. Der Ratsvorsteher gewährt Euch vollen Zugang zu ihrem Inhalt.", sourceObjective = "Holt Euch ein Beutestück aus der Großen Schatzkammer.", progress = "Stöbert nach Herzenslust in der Schatzkammer, {name}.", completion = "Ihr habt also ein paar nützliche Ausrüstungsgegenstände in der Schatzkammer gefunden?\n\nGut. Es werden dort noch viele weitere Gegenstände gelagert. Seht regelmäßig nach. Man weiß nie, was man dort findet!", sourceObjectiveStatus = "unverified-source-field" }
quests[84506] = { id = 84506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierjagd", description = "Hallo, <Abenteurer/Abenteurerin>!\n\nIch bin auf eine Gruppe von Kampfhaustierzähmern getroffen, die alle ganz begeistert über ein Bingospiel geredet haben. Unter ihnen war auch Jepetto Spaßbrumm, der eher unzufrieden mit seinem Fortschritt war.\n\nFragt ihn doch mal, ob er vielleicht Hilfe braucht.", sourceObjective = "Sucht Jepetto Spaßbrumm in der Nähe des Haustierspielplatzes auf.", completion = "Oh, Ihr wollt mir dabei helfen, seltene Tiere aufzuspüren?", sourceObjectiveStatus = "unverified-source-field" }
quests[84519] = { id = 84519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antike Kuriositäten: Kampf", description = "<Ihr haltet das Relikt in den Händen und bemerkt, dass es schimmert. Es sieht wichtig aus. Die Forscherliga wäre daran interessiert.>", sourceObjective = "Setzt den unverwüstlichen Eisengötzen ein und rüstet Brann Bronzebart damit aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[84520] = { id = 84520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antike Kuriositäten: Unterstützung", description = "<Ihr haltet das Relikt in den Händen und bemerkt, dass es schimmert. Es sieht wichtig aus. Die Forscherliga wäre daran interessiert.>", sourceObjective = "Rüstet das optimierte Relikt aus und wendet es auf Brann Bronzebart an.", sourceObjectiveStatus = "unverified-source-field" }
quests[84521] = { id = 84521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsorgliche Bestrebungen", description = "Maru hat sich als eine hervorragende Juniorschnüfflerin erwiesen. Ich denke, sie hat sich ihre eigene Denkkappe verdient!\n\nAber ich kann sie ihr nicht einfach geben. Ich habe die Teile, die sie braucht, um selbst eine anzufertigen, vergraben. Die Koordinaten für jedes Teil sind in Rätseln verborgen. Löst die Rätsel, um die Verstecke zu finden!\n\nWärt Ihr so freundlich, sie zu begleiten, um sicherzustellen, dass ihr nichts passiert? Ihr könnt meine Denkkappe benutzen, um ihr zu helfen. Ich gebe Euch auch noch ein spezielles Hinweisbuch mit, das Euch während Eures Fortschritts Rätsel offenbart.", sourceObjective = "Geleitet Maru durch Benatauks Rätsel.", progress = "Wie kommt Ihr voran? Maru macht Euch doch keine Schwierigkeiten, oder?", completion = "Ihr habt es geschafft! Seht Euch nur das breite Grinsen auf Marus Gesicht an. Ich danke Euch vielmals für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[84542] = { id = 84542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein strahlendes Echo", description = "<In Eurer Hand haltet Ihr eine kleine Azeritkugel. Ihr Licht ist gleichmäßig und hell, doch der Klang, den sie aussendet, ist klagend und sehnsüchtig. Sie zieht ganz leicht an Euch.>", sourceObjective = "Bringt das strahlende Echo zu einer Weltenseelenerinnerung und lasst es dann frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[84547] = { id = 84547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückzahlung garantiert", description = "<Sogar eine leere Kaja'Cola-Dose hat nach wie vor Wert. Vielleicht hat Zwinki Schmutzfinger Interesse daran.>", sourceObjective = "Bringt die leere Kaja'Cola-Dose zu Zwinki Schmutzfinger bei der Treibgutbank.\n\nBereitgestellter Gegenstand:", completion = "Die verwerte ich nicht wieder. Ich fülle sie einfach mit Billigmarkencola.\n\nIch verspreche Euch, den Unterschied merkt keiner!", sourceObjectiveStatus = "unverified-source-field" }
quests[84559] = { id = 84559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschnitzte Wappen", sourceObjective = "Die Arathi wissen Eure Hilfe in diesen gefährlichen Landen wirklich zu schätzen. Nehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[84563] = { id = 84563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger mit dem Spielzeug", description = "<Abenteurer/Abenteurerin>, Maru braucht wieder Eure Hilfe.\n\nEs gibt eine dringende Angelegenheit, über die sie mit Euch sprechen möchte.", sourceObjective = "Sprecht mit Maru.", completion = "Jippie, Ihr szeit hier szum Helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84564] = { id = 84564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[84566] = { id = 84566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
