quests[84583] = { id = 84583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat hier die Ho-Zen an", description = "Hallo, {name}. Kann ich Euch vielleicht nochmal um Hilfe bitten? So ein komisches Pärchen sorgt für Unruhe in der Nähe der Streichelzone.\n\nVielleicht schafft Ihr es ja, die Ho-Zen davon zu überzeugen, unsere Gäste nicht weiter anzuschreien.", sourceObjective = "Konfrontiert die lärmenden Ho-Zen.", completion = "Riko hat die Nase voll von den wuddligen Nappeln!\n\nVerfiddelt nochmal, was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[84588] = { id = 84588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Spielzeugrettung", description = "Menno! Ein lisztiger Tieb hat meinen Freunten ihre Szpielszeuge geklaut!\n\nIhr szeit gut im Sznüffeln, oter? Könnt Ihr meinem Freunt Yennu helfen, szein gesztohlenesz Szpielszeug szu finten? Ihr fintet ihn auf ten Tracheninszeln.", sourceObjective = "Findet die verschwundenen Spielzeuge.", completion = "Ihr szeid wirklich ein Rettungszexperte für Szpielszeuge! Wer, glaubszt Ihr, hat die Szpielszeuge überhaupt geklaut?\n\nWir szollten die Hinweisze durchszehen, die Ihr gefunden habszt, um den Szuldigen zu entlarven! Kommt morgen wieder, dann können wir unsz die Beweisze anszehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84595] = { id = 84595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des fell-suchenden Nappels", description = "Riko hat genug von den rammdübeligen Buddlerinos! Kyrin wünscht sich ein Fellknäuel und diese Fupfer geben nichts ab!\n\nKiryn sagt, Riko soll aufhören mit Quasseln. Sie sagt, ihre Fellis mitzunehmen, ist \"stehlen\".\n\nIhr seid ein hilfsbereiter Nappel? Findet für Kiryn einen felligen Freund! Macht Euch besser Notizen, damit Nappel nicht steckenbleibt.", sourceObjective = "Sucht einen Begleiter für Riko und Kyrin.", completion = "Ihr habt's wuddlig geschafft! Ihr seid der Beste, Nappel!", sourceObjectiveStatus = "unverified-source-field" }
quests[84616] = { id = 84616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feiern und Spaß haben!", description = "Willkommen bei der Bronzedrachenfeier!\n\nWir laden Euch ein, eine Vielzahl an Ereignissen zu genießen. Ihr könnt es zum Beispiel Eurem Haustier gleichtun und auf unserem Spielplatz herumrennen.\n\nIhr könnt aber auch an einem unserer größeren Ereignisse teilnehmen, wie dem Mode- oder dem Reittierrausch. Alle 15 Minuten beginnt ein anderes Ereignis.\n\nVielleicht habt Ihr aber auch mehr Lust auf eine Herausforderung? Wenn dem so ist, dann sprecht mit Chromie, um ihr dabei zu helfen, ihren Kodex für ihre Führungen zu entwirren.\n\nJedes Ereignis steht Euch offen. Wichtig ist nur, dass Ihr Spaß habt!", sourceObjective = "Nehmt im Zuge der Feierlichkeiten an Aktivitäten und Aufgaben von Besuchern teil.", progress = "Gefällt Euch unsere kleine Feier?", completion = "Es ist wirklich erfüllend, so viele Einwohner Azeroths und darüber hinaus auf unserer Feier zu sehen. Dadurch, dass wir uns unsere Vergangenheiten vor Augen führen, sind wir in der Lage, zusammenzukommen und gemeinsam zu feiern.\n\nWir hoffen, dass Ihr das Ereignis auch weiterhin genießen könnt. Nehmt bitte diesen Segen der Bronzedrachen an, mit dem wir Euch auf Euren eigenen Abenteuern unterstützen wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84619] = { id = 84619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knatzelfiddlerlesegruppe", description = "Die Ho-zen der Bilgerattenmannschaft sind meisterhafte Plünderer. Sie besuchen diese Insel schon seit Jahren und schnappen sich alles von Wert.\n\nUnter ihrer Beute befinden sich auch viele Forschungsmaterialien, die dabei helfen könnten, die Geschichte dieses Ortes aufzudecken.\n\nInfiltriert ihr Lager, geht an Bord ihrer Schiffe und bergt alle Bücher, Schriftrollen und Dokumente, die Ihr finden könnt.", sourceObjective = "Sammelt verschiedene Schriftstücke von Bilgerattenschiffen und Anlegeplätzen.", progress = "Habt Ihr etwas von Wert gefunden?", completion = "Welch eine faszinierende Schriftensammlung! Ich wage zu behaupten, dass ich darin die ganze Nacht lang lesen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[84621] = { id = 84621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporen eines Knappen", description = "Ihr kommen nach Campalot, um Lehnstreue zu schwören und Ritter der Wunden Tafel zu werden?\n\nSeht nicht wie ein Anfänger aus, aber selbst tapferster Ritter beginnt als Knappe. Verdient Euch Sporen. Übt in Demut.\n\nBeweist, dass Ihr sie auf gleiche Weise gelernt habt. Schaut, wie Ihr auf Burg helfen könnt.\n\nKönnte auch für andere Knappen gutes Beispiel sein.", sourceObjective = "Helft in Campalot.", progress = "Hm, wohl etwas übersehen.", completion = "Gute Arbeit, Knappe {name}. Vergesst Lektion in Demut nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[84624] = { id = 84624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandige Feierkiste", description = "<Diese Kiste hat zweifellos einen langen Weg hinter sich! Alyx wäre sicher dankbar, die Vorräte zurückzubekommen.>", sourceObjective = "Bringt die sandige Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84625] = { id = 84625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschend unversehrte Feierkiste", description = "<Ihr habt diese Kiste mit Feierutensilien in einem anonymen Grab gefunden, wo Ihr stattdessen die Knochen vergraben habt. Alyx wäre sicher dankbar, die Vorräte zurückzubekommen.>", sourceObjective = "Bringt die überraschend unversehrte Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84627] = { id = 84627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drei Köpfe der Tiefe", description = "Die Reichweite dieser Kreaturen ist wahrlich furchteinflößend!\n\nIch bin ihnen zahlreiche Male in den imperialen Gewässern begegnet. Ich kenne ihre Strategien nur zu gut und habe bereits einen Plan, wie wir ihnen beikommen können.\n\nMeine Späher habe die Position dreier ihrer Anführer ausfindig gemacht. Macht ihnen den Garaus, dann schlagen wir zu.", sourceObjective = "Eliminiert Kriegsfürst Thresh, Extraktor Silsai und Nereu der stillen Welle.", progress = "Habt Ihr ihre Anführer ausgeschaltet?", completion = "Vortreffliche Arbeit, {name}. Ich könnte jemanden Eures Kalibers auf meinem Schiff gebrauchen, solltet Ihr je auf der Suche nach Arbeit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[84638] = { id = 84638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger im Hochland", description = "Sowohl Geya'rah als auch Danath hörten von Unruhen im Arathihochland: In Stromgarde trieb es die Bürger auf die Barrikaden, während mag'harische und stromische Außenposten von Überfällen geplagt werden.\n\nDanath und Geya'rah kehren in ihre jeweilige Heimat zurück, Danath nach Stromgarde und Geya'rah nach Hammerfall, um die Spannungen zu entschärfen.\n\nIch bat darum, sie zu begleiten. Ich sehne mich seit Langem danach, die alte Verbindung meines Volkes, mich eingeschlossen, zu den Arathi wiederzubeleben. Ich möchte auch mehr über die Horde erfahren.\n\nGeya'rah hatte keine Bedenken, Danath hingegen... brauchte einige Überzeugungsarbeit.\n\nMöglicherweise habe ich auch angedeutet, dass Ihr Euch mir anschließt...", sourceObjective = "Reist ins Arathihochland mithilfe des Portals in Dornogal.", completion = "Mich hatten schon Berichte erreicht, wonach Banditen im Hochland ihr Unwesen treiben, aber... ich wusste nicht, dass es so übel ist.\n\nDass wir mitten in diese Attacke hineingerierten, macht die Sache nun auch nicht mehr schlimmer.\n\nWenn wir der Sache auf den Grund gehen wollen, können wir genauso gut hier beginnen.\n\nIch... wünschte nur, Faerin wäre nicht hier, um es mitanzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84639] = { id = 84639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackeln und Fässer", description = "Die Angriffe sind für uns nichts Neues, aber diesmal...\n\n<Gänger erschaudert.>\n\nDiesmal war es anders.\n\nSie wollten kein Vieh, kein Korn, nicht mal Geld. Sie haben Fackeln und ein paar Fässer Teer erbeutet, mit dem wir sonst unsere Dächer reparieren.\n\nIch weiß nicht, was sie damit vorhaben, aber... ich kann's mir denken. Sie wollen irgendwas niederbrennen.\n\nIhr müsst sie aufhalten, bevor sie den nächsten Hof überfallen!", sourceObjective = "Holt 10 gestohlene Fackeln von Banditen der Defias und 10 Teerfässer vom Gehöft von Neuhof zurück.", progress = "Ich hoffe, was immer sie im Schilde führen, hat nichts mit meinen Nachbarn zu tun. Oder mit Stromgarde!", completion = "Vielen Dank, {name}.\n\nDamit habt Ihr hoffentlich im Keim erstickt, was sie vorhatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84640] = { id = 84640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungutes Abzeichen", description = "<Dieser Bandit der Defias trug ein Abzeichen mit einem Emblem, das Ihr nicht wiedererkennt.\n\nEs zeigt eine aufgehende Sonne, die ihre Strahlen aussendet. Die Sonne und die Strahlen sind rot bemalt.\n\nVielleicht kann Danath das Abzeichen identifizieren.>", sourceObjective = "Bringt das unvertraute Emblem zu Danath Trollbann am Gehöft von Neuhof.\n\nBereitgestellter Gegenstand:", completion = "Ich erkenne das Emblem nicht. Einer der Defias trug es an sich, sagt Ihr?\n\nHm. Seltsam.\n\n<Danath dreht und wendet das Abzeichen in seiner vom Kampf gezeichneten Hand, während sich seine Mine verfinstert.>\n\nIch frage mich, was es bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84641] = { id = 84641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten", description = "Ein Angriff der Defias. Gestohlene Fackeln und Teerfässer. Eine Gruppe namens Rote Dämmerung, die hier im Herzen des Hochlands Anhänger rekrutiert...\n\nStromgrade hatte gute Gründe, in einem Schreiben um meine Rückkehr zu bitten. Was ist hier los?\n\nIch übertrug die Verantwortung an Oberst Nials, nachdem Marran für ihr irriges Vorhaben eingesperrt wurde. Ich muss nach Stromgarde eilen und sofort mit Nials sprechen.", sourceObjective = "Trefft Euch mit Danath Trollbann an den Toren von Burg Stromgarde.", completion = "Es ist viel schlimmer, als ich dachte. Nach den Angriffen auf unsere Versorgungslinien sind die Leute wütend und hungrig... und sie suchen nach einem Schuldigen. Unsere Nachbarn in Hammerfall sind da leider die naheliegende Wahl.\n\nWir dürfen nicht zulassen, dass diese Unruhen weitergehen. Ich muss mit Nials und meinen Beratern sprechen.\n\nWie ich sehe, hat Faerin ihre und Eure Hilfe angeboten, um die Not in Stromgarde zu lindern. Ich mute Euch nur ungern zu, was im Grunde eine diplomatische Mission ist, aber wenn Ihr Bräustein helfen würdet, während ich mit Nials spreche, hätte ich eine Sorge weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[84643] = { id = 84643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer Ärger mit den Wutbürgern", description = "Ich bin sehr dankbar für Eure Hilfe. Mit den Truppen, die wir nach Khaz Algar entsandten, dem Kampf gegen die Bedrohungen im Hochland, ganz zu schweigen von den Fahnenflüchtigen, haben wir nicht genug Soldaten, um für Ordnung zu sorgen.\n\nMarrans wütende Unterstützer sorgen in der Stadt für Ärger. Sie plündern Vorräte, bedrohen die Leute und machen uns das Leben noch schwerer. Wir haben eine Ausgangssperre verhängt, aber Marrans Anhänger widersetzen sich ihr offen.\n\nDreht als meine Abgesandten eine Runde durch die Stadt und befehlt den Unruhestiftern, nach Hause zu gehen. Und wenn sie weiter Ärger machen, habt Ihr meine Erlaubnis, ihnen eine Lektion zu erteilen.", sourceObjective = "Kümmert Euch um 15 Unterstützer von Marran in Stromgarde.", completion = "Es ist wirklich entsetzlich. Sie versuchen, rechtschaffene Bürger einzuschüchtern und zu vertreiben, bloß weil sie keine Menschen sind. Und wenn jemand widerspricht, wird er vom Mob niedergebrüllt.\n\nViele versuchen, ihnen aus dem Weg zu gehen, aber sie postieren sich mit Absicht dort, wo man ihnen nicht entgehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[84645] = { id = 84645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Postweg", description = "Der Handel in Stromgarde ist zum Erliegen gekommen. Nach den Angriffen fehlt es uns an Waren genau wie an Arbeitern.\n\nNials war zu beschäftigt, also habe ich selbst offizielle Hilfeersuchen verfasst.\n\nDie meisten Anliegen sind ziemlich simpel: Schreiben mit der Bitte um Vorräte und dergleichen für die Stromgarder Armee.\n\nDie Unterlassungserklärung für Joseph ist etwas anderes. Er beschuldigt lauthals alle, die keine Menschen sind, für unseren Notstand verantwortlich zu sein. Jemand muss ihm offiziell einen Maulkorb verpassen, sonst zettelt er mit seiner Hetze noch einen Aufstand an.\n\nWürdet Ihr als meine Abgesandten die Hilfeersuchen durchsetzen?", sourceObjective = "Stellt Bräusteins Anfragen den Leuten in Stromgarde zu.", completion = "Ihr habt meinen Dank und den Dank von Stromgarde.\n\nEs tut mir leid, dass Ihr Euch Josephs Gemecker anhören musstet, aber wenigstens hat er friedlich das Feld geräumt.\n\nAuch wenn es nicht den Anschein erweckt, ist die Stadt Lord Trollbann weiterhin treu ergeben. Größtenteils.\n\nMarrans Anhänger sind bloß eine laute und wütende Minderheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[84649] = { id = 84649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marran Trollbann", description = "Ich bin Oberst Veronika Nials und Statthalterin von Stromgarde in Lord Trollbanns Abwesenheit.\n\nIch bin mir sicher, Ihr habt in Stromgarde oft genug den Namen \"Marran\" gehört, als Ihr unserem Volk geholfen habt. Marran Trollbann ist Danaths Nichte. Sie war kurzzeitig die Regentin, während Lord Danath Trollbann seine Truppen in Khaz Algar anführte.\n\nNach ihrem schändlichen Tun in seiner Abwesenheit ließ Lord Trollbann sie einsperren, als er zurückkehrte.\n\nDennoch war er der Meinung, Faerin sollte mit ihr sprechen. Vielleicht, um... ihren Blickwinkel besser zu verstehen. Ich kann Euch zu ihr bringen, wenn Ihr wünscht.", sourceObjective = "Wohnt dem Gespräch zwischen Faerin Lothar und Marran Trollbann in der Kaserne von Burg Stromgarde bei.", completion = "Marran mag nun im Gefängnis sitzen, aber ihre Unterstützer verbreiten ihre hasserfüllten Ansichten weiter im ganzen Hochland.\n\nWas immer sie behaupten mag, ich glaube nicht, dass sie Anführerin dieser \"Roten Dämmerung\" ist, von der Ihr beide sprecht.\n\nIch behalte im Blick, wer kommt und geht. Sie bekommt keine Besucher von außerhalb.", sourceObjectiveStatus = "unverified-source-field" }
quests[84650] = { id = 84650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Zuflucht", description = "Wenn Ihr Lord Trollbann sprechen möchtet, um Eure Theorie zu Marran mit ihm zu teilen, muss ich Euch enttäuschen. Ein Schreiben rief ihn dringend nach Hammerfall, das weit im Osten von hier liegt.\n\nMöglicherweise hat er auf dem Weg an der Zuflucht Halt gemacht, einem stromischen Lager ungefähr auf halber Strecke zur Orcstadt. Nach den häufigen Banditenangriffen in der Gegend wollte er meines Wissens dort vorbeisehen und sicherstellen, dass unsere Leute wohlauf sind.\n\nVielleicht erwischt Ihr ihn dort.", sourceObjective = "Sucht nach Danath an der Zuflucht im Arathihochland.", progress = "Es ist schön zu erleben, wie Menschen und Orcs zusammenkommen, um einander zu helfen.\n\nWenn bloß die Arathi hier hätten sehen können, was ich in Khaz Algar gemacht habe.", completion = "Noch ein Banditenangriff? Und sie tragen das gleiche Emblem wie die Halunken bei Neuhof?\n\nWenn das mit der Roten Dämmerung und Marran zu tun hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[84651] = { id = 84651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bekanntes Gesicht", description = "Anfangs wirkten diese Angriffe auf unsere Siedlungen, als würde eine wilde Meute von Banditen um Ressourcen streiten.\n\nInzwischen sind sie besser koordiniert. So als würden sie als Gruppe zusammenarbeiten.\n\nDas sind schlechte Neuigkeiten für alle.\n\nAber solch rivalisierte Banden würden nicht gemeinsame Sache machen, wenn sie keinen starken Anführer hätten. Und ohne diesen Anführer hält es die Banditentruppe nicht lange zusammen.\n\nWenn Ihr helfen wollt, spürt den Anführer dieses Angriffs auf die Zuflucht auf und macht ihn einen Kopf kürzer.", sourceObjective = "Bezwingt den Anführer des Angriffs auf die Zuflucht.", completion = "Er ist entkommen?\n\n<Karga spuckt auf den Boden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[84652] = { id = 84652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringender Nachschub", description = "Stromgardes Truppen sind in Khaz Algar und können die äußeren Siedlungen nicht beschützen.\n\nHammerfall hilft, wo es kann, aber auch wir kämpfen in Khaz Algar.\n\nWir haben viele stromische Flüchtlinge in Hammerfall aufgenommen, aber sie zu ernähren, hat unsere Vorräte stark dezimiert.\n\nVielleicht gibt es einen Weg, mehr Leute satt zu bekommen.\n\nVikki erwähnte, dass die Zuflucht ein Vorratslager für die umliegenden Siedlungen ist. Wenn wir einige Vorräte in die Hände bekommen, können wir in Hammerfall mehr Flüchtlinge versorgen.", sourceObjective = "Sammelt 4 Vorratskisten in der Zuflucht ein.", completion = "Gut, {name}.\n\nIch hoffe, Stromgarde nimmt es uns nicht übel, dass wir diese Vorräte für ihre Flüchtlinge \"borgen\".\n\nHeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[84656] = { id = 84656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Hammerfall", description = "Erst der Überfall auf das Gehöft von Neuhof durch die Defias, nun ein Angriff auf die Zuflucht durch die Scharlachroten Kreuzzügler.\n\nUnterschiedliche Gruppen von Banditen, und doch reden beide vom Gleichen: der \"Roten Dämmerung\", und sie tragen dasselbe Emblem.\n\nAuch Joseph ist direkt in all das verstrickt.\n\nEs wirkt, als wären all diese Fäden miteinander verwoben... und sie führen zurück zu Marran.\n\nDanath muss von all dem erfahren. Wenn er nicht mehr hier ist, dürfte er sich bereits in Hammerfall aufhalten.\n\nWir sollten uns unverzüglich auf den Weg dahin machen.", sourceObjective = "Trefft Faerin Lothar in Hammerfall im Arathihochland.", completion = "Wenn Danath nicht hier ist... Wo ist er dann?", sourceObjectiveStatus = "unverified-source-field" }
quests[84657] = { id = 84657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Stromgarde", description = "Etrigg hatte recht. Die Rote Dämmerung versucht tatsächlich, einen Konflikt zwischen Horde und Allianz zu entfachen.\n\nWir müssen sofort nach Stromgarde zurückkehren und Oberst Nials berichten, dass Danath entführt wurde. Sie wird gewiss all ihre Kräfte für die Suche mobilisieren!\n\nKommt,{name}. Wir dürfen keine Zeit verlieren!", sourceObjective = "Kehrt nach Stromgarde zurück und ersucht Oberst Nials um ihre Hilfe bei der Suche nach Danath.", completion = "<Bräustein beugt sich zu Euch vor und spricht kaum lauter als ein Flüstern.>\n\nGut, dass ich Euch gefunden habe. Ich brauche jeden Verbündeten, den ich kriegen kann.\n\nIhr habt großes Glück, dass sie Euch am Leben gelassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84658] = { id = 84658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie finden", description = "Wo ist meine Mama? Mein Papa?\n\nEllie?\n\n<Maggie blickt sich mit Tränen in den Augen um.>\n\nIch bin dem Herrn Gresham und Clarabelle gefolgt, als wir die Banditen sahen. Er hat mich gepackt und wir sind hierher gerannt.\n\nIch weiß nicht, wo Mama, Papa und Ellie sind.\n\nKönnt Ihr sie für uns finden? Clarabelle beginnt schon, sich Sorgen zu machen...\n\n<Maggie schnieft.>", sourceObjective = "Findet heraus, welches Schicksal Marschall Welkshain, Sharon Welkshain und Ellie auf dem Gehöft von Neuhof ereilt hat.", progress = "Ellie muss so verängstigt sein!", completion = "Ihr habt sie gefunden! Ihr habt sie wirklich gefunden! Habt tausend Dank!\n\n<Maggie schließt Ellie fest in ihre Arme.>", sourceObjectiveStatus = "unverified-source-field" }
quests[84659] = { id = 84659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Faerin", description = "Ich habe gesehen, wie Faerin fortgeschleppt wurde, doch ich konnte ihr nicht folgen, ohne selbst entdeckt zu werden. Sie wird vermutlich in einem anderen Gebäude gefangen gehalten.\n\nGeht und findet sie. Hoffentlich lebt sie noch...\n\nUnd seht, ob Ihr weitere Hinweise auf die Rote Dämmerung finden könnt. Es gibt keinen Grund, weshalb wir so rasch hätten übermannt werden sollen. Oberst Nials und Lady Trollbann haben gewiss überall ihre Spießgesellen installiert.\n\nJe mehr Informationen wir haben, desto besser können wir sie einsetzen, wenn wir zum Gegenschlag ausholen.", sourceObjective = "Durchsucht die Gebäude in Stromgarde nach Faerin und Informationen über die Rote Dämmerung.", completion = "Ich bin froh, dass es Faerin gutgeht.\n\nUnd diese Informationen, die Ihr gefunden habt...\n\n<Bräustein sackt zusammen.>\n\nWenn man verzweifelt ist, glaubt man an jedes Versprechen auf ein besseres Leben, ganz gleich, von wem es stammt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84664] = { id = 84664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterwelt steht Kopf", description = "Hey, Überkrabbler. Ihr seht da ziemlich fehl am Platze aus. Wurdet Ihr von einem Luftschiff angefahren, oder was?\n\nEgal. Spielt keine Rolle. Von Fremdling zu Fremdling: Wenn Ihr hier unten überleben wollt, müsst Ihr die Regeln der Straße kennen. Gold ist schön und gut, wo Ihr herkommt, aber hier unten werdet Ihr Kej brauchen - und zwar jede Menge davon.\n\nAlso. Betrachtet dies als Zeichen des guten Willens von Lady Pedipalps da oben. Holt Euch etwas Schönes.", sourceObjective = "Gebt bei einem der Händler im Nest der Weberin Kej aus.", progress = "Habt Ihr eine Einzelhandelsallergie oder so was? Nun geht und lebt mal ein bisschen!", completion = "Habt Ihr Euch gut umgesehen? Hier ist es ziemlich unheimlich, selbst für ein gerissenes Mädchen wie mich. Aber wenn Ihr genug Kej zusammenbekommt, könnt Ihr alle möglichen Sachen kaufen - sowohl hier als auch in der Stadt der Fäden.\n\n<Linny mustert Euch von Kopf bis Fuß.>\n\nAndererseits werdet Ihr wahrscheinlich trotzdem gefressen, also seht Euch vielleicht lieber schöne nerubische Grabsteine an.", sourceObjectiveStatus = "unverified-source-field" }
quests[84667] = { id = 84667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.O.L.E.M. des Fortschritts", description = "Die Bürger von Lorenhall rufen verzweifelt um Hilfe! Sie brauchen Schutz! Sie brauchen Freude! Sie brauchen mehr, um über die Runden kommen!\n\nAls Erfinder habe ich mein Leben lang an etwas getüftelt, das die Probleme unseres Volkes löst. Und ich glaube, es ist bereit für einen Testlauf. Ich nenne es meinen Goblinschen Optimalen Lebens-Ertüchtigungs-Mechanismus, oder kurz G.O.L.E.M.!\n\nFindet jemanden mit Problemen und probiert ihn aus. Und nehmt doch meinen Sohn mit. Pitz hat vielleicht nichts von meinem Erfindergeist geerbt, aber er weiß, wie er mit den Nachbarn ins Gespräch kommt.", sourceObjective = "Dreht mit dem G.O.L.E.M. eine Runde durch die Bottichwerke und löst Probleme für Gart Taschens, \"Knatschi\" Omi und die Kinder von Lorenhall.", completion = "Tja, war schön, solange es funktioniert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[84672] = { id = 84672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müllabholung", description = "Mein alter Herr hat all diese verrückten Ideen, um die Welt besser zu machen... Ich weiß ja nich'. Ich versteh kein Stück von Maschinen, aber deshalb bin ich wohl nie der Erfinder geworden, den er so gern in mir gesehen hätte.\n\nAber ich hab auch Ideen, wie man die Probleme hier lösen könnte. Wie dieses verdammte Ungeziefer, das die ganzen Straßen verschmutzt!\n\nDas würde vielleicht nicht die Moral der ganzen Gemeinde revitalisieren oder so, aber ich wette, die Leute wären ein bisschen glücklicher, wenn wir die Straßen säubern.", sourceObjective = "Sammelt 12 Abfälle ein und nutzt die Verbrennungsfunktion des G.O.L.E.M., um sie zu entsorgen.", progress = "Toxische Dämpfe? Nö, so riecht's in Lorenhall eben!", completion = "Hier sieht es schon viel sauberer aus! Vielleicht ist an dieser G.O.L.E.M.-Sache wirklich was dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[84673] = { id = 84673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genialer Erfinder...-s Sohn", description = "Ich... mag nicht so ein genialer Erfinder sein wie mein alter Herr. Nicht mal ein mittelmäßiger Erfinder, um ehrlich zu sein. Mein Meisterwerk ist dort an der Wand, aber es braucht noch viel Arbeit, damit es... irgendwas macht.\n\nAber das! Das könnte meine große Chance sein, um Paps zu beweisen, dass ich ihn stolz machen kann!\n\nWir müssen nur noch, äh, rauszufinden, wie man dieses Ding repariert. Kann doch nicht so schwer sein, oder?", sourceObjective = "Helft Pitz, den G.O.L.E.M. zu reparieren.", completion = "Das ist nicht gut. Es funktioniert überhaupt nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[84674] = { id = 84674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der G.O.L.E.M. ist durchgedreht!", description = "Der G.O.L.E.M. ist durchgeknallt! Außer Rand und Band!\n\nIch muss ihn wieder einfangen. Wer weiß, was für ein Unheil eine so mächtige Erfindung anrichten könnte! Und stellt Euch mal vor, wie böse Papa wäre, wenn er rausfindet, dass wir das Ding verloren haben!\n\nIch bitte Euch echt ungern, hinter mir aufzuräumen, aber jemand muss hier bleiben und wieder alles in Ordnung bringen. Würdet Ihr das tun?", sourceObjective = "Beseitigt das Chaos, das der G.O.L.E.M. angerichtet hat.", progress = "Pitz! Hat irgendjemand Pitz gesehen?", completion = "So viel Chaos... was hat der G.O.L.E.M. nur angerichtet?!", sourceObjectiveStatus = "unverified-source-field" }
quests[84675] = { id = 84675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duell unterm Dach", description = "Ich war so blind! Alles fällt auseinander!\n\nDie Nachbarschaft ist in schäbigerem Zustand als je zuvor, und der G.O.L.E.M. ist schuld! Und mein Junge, mein geliebter Pitz...\n\nEr ist in dieses Gebäude gerannt, um die Höllenapparatur aufzuhalten. Ach, ich war immer so hart zu ihm, und jetzt sehe ich ihn vielleicht nie wieder...\n\nIhr müsst ihn finden. Und diesem mechanischen Monstrum ein für alle mal den Stecker ziehen.", sourceObjective = "Rettet Pitz und zerstört den G.O.L.E.M.", progress = "Meine Hybris... Das ist das Erste, was man auf dem Erfinderkolleg lernt! Warum habe ich nicht zugehört!", completion = "Wisst Ihr... Er mag kein großer Erfinder sein, aber ich bin mächtig stolz auf den Burschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84680] = { id = 84680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haucht Fels und Stein Leben ein", description = "Die angreifenden Vrykul hetzen Salz- und Salzsteinelementare auf ihre Feinde.\n\nUm ihren Angriff abzuwehren, können auch wir sie nutzen.\n\nVerwendet diesen Felsbeleber, um die Elementare aus den nahe gelegenen Steinen freizusetzen und sie in mächtige Verbündete zu verwandeln. Mit ihrer Hilfe sollten wir in der Lage sein, die Bedrohung durch die Vrykul abzuwenden.", sourceObjective = "Belebt 8 rastlose Kiesel und Steine und besiegt 8 Salzblutschrecken und Salzblutmonstrositäten.", progress = "Habt Ihr die Vrykul und ihre Elementarknechte bereits aufgehalten?", completion = "Ihr habt die Elementare gut eingesetzt, {name}. Ich freue mich schon auf weitere Vorführungen Eurer Fähigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84682] = { id = 84682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Pakten und Parteien", description = "Die Durchtrennten Fäden sind für Euch und Eure Verbündeten bereit. Ihr werdet eine brennende Fackel für Ansureks Netze sein.\n\nDer General, der Wesir und ich, die Weberin, haben jeweils unterschiedliche Methoden, unsere Feinde zu bekämpfen... und unterschiedliche Vorteile, wenn wir unseren Komplizen helfen. Vielleicht möchtet Ihr einer Methode den Vorzug geben oder Euch stattdessen mit allen dreien beschäftigen.\n\nTrefft Euch mit unseren Vertretern und informiert Euch über unsere unterschiedlichen Methoden. Dann könnt Ihr Euren ersten Pakt schmieden.\n\nKeine Sorge, kleiner Happen - keine Entscheidung ist endgültig.", sourceObjective = "Sprecht mit den Vertretern der Durchtrennten Fäden und schmiedet dann Euren ersten Pakt.", progress = "Habt Ihr über die verschiedenen Möglichkeiten nachgedacht?", completion = "Mögen sich die Parteien des Pakts gewogen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[84683] = { id = 84683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab in die Gosse", description = "Was macht Ihr hier? Ein bisschen Sabotage?\n\nKann ich verstehen. Die Dinge laufen hier echt aus dem Runder. Aber wenn wir dieses Rohr zum Platzen bringen, wird's nur noch schlimmer. Schwarzblut überall. Wenn wir unsere Köpfe zusammenstecken, fällt uns vielleicht was Besseres ein.\n\nKommt mich in Gossenheim besuchen. Da unterhalten wir uns weiter, weg von diesen fürchterlichen Schleimen!", sourceObjective = "Trefft Pamsy in Gossenheim.", completion = "Schreit doch nicht so! Ich hab noch nie so viele Spione in Gossenheim geseh'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[84684] = { id = 84684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattsenschwanz", description = "Ich habe eine Vulpera gesehen, die sich überaus verdächtig verhalten hat. Sie wirkte... außer sich. Ich meine, ein Messer an ihrer Seite und Augen voller dunkler Magie gesehen zu haben.\n\nSie hat bemerkt, dass ich sie angestarrt habe, und ist sofort getürmt. Ist sie eine gesuchte Verbrecherin?\n\nSie... hat das hier fallen lassen. Hier.", sourceObjective = "Spürt Ratts auf.", progress = "<Ratts scheint vor lauter Eile diesen Edelstein fallen gelassen zu haben.>", completion = "<Was könnte der Zweck des Edelsteins sein, den Ratts zurückgelassen hat?>", sourceObjectiveStatus = "unverified-source-field" }
quests[84693] = { id = 84693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkstisch im Nest der Weberin", description = "Überreicht diese Marke Ak'itaz im Nest der Weberin, um Euren eigenen Handwerkstisch herstellen zu lassen.", sourceObjective = "Sprecht mit Ak'itaz im Nest der Weberin.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr da? Ah! Ich werde einen Tisch für Euch herstellen. Was für einen möchtet Ihr?\n\nArbeitet Ihr mit Fleisch, Metall oder Magie?", sourceObjectiveStatus = "unverified-source-field" }
quests[84700] = { id = 84700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pakte in der Tiefe", description = "Diese Weberratte trägt eine Nachricht auf ihrem Körper. Sie ist an Euch gerichtet und stammt von der Witwe Arak'nai.\n\n\"Liebster Happen,\n\nich und die anderen Mitglieder unseres Triumvirats der Durchtrennten Fäden bitten um Eure Anwesenheit. Azj-Kahet selbst steht am Rande einer Evolution, aber wir werden Eure... einzigartigen Methoden brauchen, wenn sie erfolgreich sein soll.\n\nUnd wie immer werden die Belohnungen für Euch und Eure Sache ganz großartig sein.\"", sourceObjective = "Geht zur Witwe Arak'nai im Nest der Weberin.", completion = "Vielen Dank, dass Ihr den Weg zurück in mein bescheidenes Nest auf Euch genommen habt.\n\n<Ein tiefes Kichern ertönt aus der Witwe Arak'nai.>\n\nWir haben Großes mit Euch vor. Ganz bestimmt, ganz bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84701] = { id = 84701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sprecher", description = "Es gibt also noch jemanden, der etwas Ähnliches erlebt hat wie ich. Und doch ist es nicht dasselbe.\n\nIch muss mit ihm sprechen.", sourceObjective = "Sprecht mit Magni in Dornogal.", completion = "Seid Ihr gekommen, um Euch zu verabschieden?", sourceObjectiveStatus = "unverified-source-field" }
quests[84704] = { id = 84704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine andere Perspektive", description = "Danath ist nicht hier.\n\nFaerin sagt, er sei nach Hammerfall gereist, weil wir angeblich ein Treffen verlangt hätten. Doch ich habe keine solche Botschaft an ihn gesandt, noch an sonst jemanden.\n\nIch werde sofort die Vorhut aussenden, um nach ihm zu suchen.\n\nWarten wir auf ihre Rückkehr... Euer und Kargas rasches Handeln könnte unseren menschlichen Flüchtlingen das Leben gerettet haben. Wir hatten keinerlei Nahrung mehr, die wir ihnen hätten geben können.\n\nVerteilt die Kisten direkt an sie. Ich bin mir sicher, sie werden für das darin enthaltene Essen dankbar sein.", sourceObjective = "Stellt 4 Vorratskisten bei den arathischen Flüchtlingen auf, die in Hammerfall Zuflucht gesucht haben.", completion = "Ich habe nie wirklich erkannt, wie viel mein Volk mit den Orcs gemein hat. Wir sind beide fern der Heimat, wir sind beide autark, wir sind beide Völker, die in den Krieg hineingeboren wurden...\n\nUnd vor allem ihr Sinn für Pflicht und Ehre ist dem unseren ebenbürtig.\n\nIch fühle mich hier... fast mehr zu Hause als in Stromgarde.", sourceObjectiveStatus = "unverified-source-field" }
quests[84705] = { id = 84705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleichborken erbleichen lassen", description = "Die Bleichborken haben schon immer genervt, seitdem ich hier bin. Aber jetzt?\n\nEtwas hat ihren Zorn entfacht. Sie greifen menschliche Siedlungen an. Vielleicht ist die Rote Dämmerung wieder schuld daran.\n\nEtrigg hat uns befohlen, den Menschen zu helfen, die sie angreifen. Wir haben unsere Patrouillen verstärkt und Flüchtlinge aufgenommen.\n\nAber wir brauchen jemanden, der in ihr Dorf geht und den Bleichborken ordentlich die Stirn bietet. Sie sind übermütig. Sie denken, sie könnten ungestraft unsere Vorhut angreifen!\n\nLasst sie daran zweifeln.", sourceObjective = "Tötet 15 Trolle der Bleichborken im Lager der Bleichborken.", completion = "Bah.\n\nDas wird sie sicherlich einschüchtern. Es würde mich wundern, wenn ich in nächster Zukunft einen von ihnen außerhalb ihres Dorfes sehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[84706] = { id = 84706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrecherfamilie", description = "Dieser Syndikatmensch kam zu uns und bot uns Informationen im Austausch für eine Rettungsmission an. Das Syndikat war uns in letzter Zeit ein Dorn im Auge, und ich wollte ihn schon fast an Ort und Stelle zerteilen.\n\nDoch er behauptet, über wichtige Informationen zu verfügen, und angesichts der Neuigkeiten über Danaths Verschwinden... könnte es das Risiko wert sein, das zu tun, was er verlangt.\n\nEr hat drei Brüder, die im Lager der Bleichborken gefangen gehalten werden. Geht hinein, findet sie, und wenn sie noch leben, befreit sie.", sourceObjective = "Rettet Kammor, Holt und Perry vor den Trollen der Bleichborken im Lager der Bleichborken.", completion = "Barclay hat Glück, dass Ihr seine Brüder rechtzeitig erreicht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84707] = { id = 84707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll treffen", description = "Ich habe noch nichts von der Vorhut gehört, aber Etrigg hat Geya'rah noch nicht von Danaths Verschwinden berichtet.\n\nIch habe ihm gesagt, dass wir ihr die Nachricht überbringen würden.\n\nSie ist auf Go'Sheks Hof und hat dort mit einem Angriff der Bleichborkentrolle alle Hände voll zu tun. Etrigg sagt, dass sie in letzter Zeit immer aggressiver werden.\n\nIch muss unweigerlich an die Geschichte dort denken, an die Trollkriege und die Schlachten der Arathi. Aber ich gebe zu, dass ich sie nun anders wahrnehme, nachdem ich mehr über die Horde erfahren habe.\n\nLasst uns gehen. Wir können nach Danath Ausschau halten, während wir dort draußen sind.", sourceObjective = "Trefft Oberanführerin Geya'rah auf Go'Sheks Hof.", completion = "Faerin hat mich von Danaths Verschwinden unterrichtet. Obwohl das... beunruhigend ist... können wir noch nicht nach Hammerfall zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[84708] = { id = 84708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Syndikat schlägt zurück", description = "Dieser Mensch behauptet, der Syndikatabschaum plane einen Angriff auf Hammerfall! An einem anderen Tag würde mich das nicht beunruhigen. Doch da die Vorhut mit den Bleichborken beschäftigt ist und nach Danath sucht, ist Hammerfall ungeschützt!\n\nLasst uns aufbrechen, {name}. Wir müssen unser Zuhause verteidigen!", sourceObjective = "Trefft Oberanführerin Geya'rah in Hammerfall.", completion = "Ich hätte hier sein sollen. Ich hätte etwas tun können.\n\n<Glühendheiße Wut und Zorn gehen von Geya'rahs angespannter Haltung und ihren geballten Fäusten aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[84709] = { id = 84709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer fallen", description = "<Etrigg knurrt vor Frustration.>\n\nIch war ein Narr!\n\nIch hätte die Vorhut nicht fortschicken dürfen. Ohne sie hat das Syndikat Hammerfall überrannt.\n\nUnd wäre da nicht mein törichtes Herz gewesen... Die \"Flüchtlinge\" entpuppten sich als Spione des Syndikats, verflucht seien ihre schmierigen Bälge...\n\nAber nun seid Ihr hier. Nun können wir das Syndikat vertreiben. Eliminiert ihre Soldaten und rettet die gefangenen Zivilisten.\n\nDiese Spione kennen meine offene Hand schon viel zu gut. Nun werden sie meine Fäuste zu spüren bekommen!", sourceObjective = "Eliminiert Soldaten des Syndikats und rettet gefangene Zivilisten in Hammerfall.", completion = "Es sind noch einige Versprengte des Syndikats in der Umgebung, doch Hammerfall gehört wieder der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[84710] = { id = 84710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsaugersammlung", description = "Ich erhaschte einen Blick auf den Anführer des Angriffs.\n\nJoseph der Erleuchtete ist wohl doch nicht nur ein Schwätzer.\n\nIst er nun Teil des Syndikats? Ich dachte, er gehöre zum \"Kreuzzug\". Aber ich schätze, das spielt nun keine Rolle mehr. Wenn wir den Angriff aufhalten wollen, müssen wir ihn ausschalten.", sourceObjective = "Besiegt Joseph den Erleuchteten in Hammerfall.", progress = "Ich gehe davon aus, dass er wieder davonläuft, so feige, wie er ist.", completion = "Joseph ist erneut entkommen und diesmal war seine Warnung noch viel unheilvoller. Er hat Dunkelheit in seinem Geist... und in seiner Seele.\n\nIch bin... verwirrt. Wie kann er behaupten, dem Licht zu folgen?", sourceObjectiveStatus = "unverified-source-field" }
quests[84711] = { id = 84711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danaths Verschwinden", description = "Meine Vorhut hat eine zerstörte Karawane auf der Straße entdeckt.\n\nUm sie herum lagen tote stromische Soldaten.\n\nEs könnte Danaths Eskorte sein. Oder eine andere unglückliche Gruppe.\n\nWie dem auch sei, wir müssen dem nachgehen. Hoffen wir, dass Danath nicht unter den Toten ist.", sourceObjective = "Trefft Oberanführerin Geya'rah am Wegekreuz des Arathihochlands.", completion = "Dies war keine Schlacht. Es war ein Hinterhalt und ein Massaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[84712] = { id = 84712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Flagge", description = "Dies wurde nicht von einfachen Banditen verübt. Dieser Ort wurde gezielt für einen Hinterhalt gewählt. Und diese Truppen wurden schnell und effizient ausgeschaltet.\n\nWenn Danath auf dem Weg nach Hammerfall war, so ist dies der direkteste Weg. Das macht ihn berechenbar.\n\n<Geya'rah verzieht das Gesicht.>\n\nWir müssen unter den Toten nach Danath suchen und herausfinden, was hier geschehen ist. Dreht jeden Stein um.", sourceObjective = "Untersucht die Gegend nach Hinweisen auf Danaths Verschwinden.", completion = "Es ist entschieden.\n\nWenn wir den Krieg verhindern wollen, müssen wir die Allianz über die Lage informieren und Danath so schnell wie möglich retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84713] = { id = 84713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Festung", sourceObjective = "Trefft Etrigg in Ar'gorok.", completion = "Ich glaube, wir haben herausgefunden, wo sich die Rote Dämmerung versteckt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[84714] = { id = 84714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles Liebe aus Eisenschmiede", description = "Diese \"Rote Dämmerung\" hält nun die Festung Ar'gorok besetzt. Banditen jeglicher Art und Herkunft haben sich unter ihrem Banner dort verschanzt.\n\nUnd zweifellos haben sie ihre Beute mitgebracht.\n\nEs könnte die Spannungen abbauen, wenn wir das zurückholen, was sie gestohlen haben, und es den rechtmäßigen Besitzern im Arathihochland zurückgeben.\n\nSeht nach, ob sie etwas bei sich führen.", sourceObjective = "Sammelt 20 gestohlene Eisenschmiedevorräte von den Truppen der Roten Dämmerung in Ar'gorok.", progress = "Wer weiß, was wir finden werden.\n\nWas sie gestohlen haben, könnte aus dem Arathihochland stammen oder gar aus den Hauptstädten der Horde oder der Allianz.", completion = "Noch mehr Vorräte? Gut.\n\nHm... Sieht so aus, als wären sie auf dem Weg von Eisenschmiede nach Stromgarde gewesen.\n\nNach dem, was Faerin mir berichtet hat, werden die Stromgarder überaus erfreut sein, dass wir sie gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84715] = { id = 84715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Danath", description = "Ar'gorok als Basis zu nutzen, war klug. Sehr klug.\n\nEs scheint, als sei der Großteil ihrer Streitmacht hier konzentriert. Wenn Danath noch lebt, halten sie ihn gewiss hier fest.\n\nDurchsucht die Gebäude nach ihm. Und haltet Ausschau nach jeglichen Hinweisen auf die Rote Dämmerung, die wir gegen sie verwenden könnten. Alles, was wir finden, mag von Wert sein, um sie zu zerschlagen.\n\nLasst uns hoffen, dass Danath noch lebt. Denn wenn nicht... dann steht uns ein langer und blutiger Krieg bevor.", sourceObjective = "Durchsucht die Gebäude in Ar'gorok nach Danath und Informationen über die Rote Dämmerung.", progress = "Danath ist hier, doch wir brauchen einen Schlüssel, um die Tür zu öffnen!", completion = "Ihr habt einen Schlüssel gefunden?\n\nGenau das, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84716] = { id = 84716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Stromgarde", description = "Während ich mich schlafend stellte, hörte ich die Wachen über die Pläne der Roten Dämmerung für Stromgarde prahlen.\n\nMeine Entführung war nur der Anfang.\n\nOberst Nials! Nach all diesen Jahren! Sie soll das Startsignal geben, indem sie Marran, meine Nichte, befreit, damit diese ihren Willen durchsetzen und einen Aufstand anzetteln kann!\n\nMarran wird Stromgardes Armee und die Rote Dämmerung nach Hammerfall führen, um das Hochland für \"Strom\" zu sichern.\n\n<Danaths Gesicht ist rot vor Zorn, doch Tränen steigen in seine Augen.>\n\nWir müssen unsere Verbündeten sammeln... und diesen Verrätern entgegentreten!", sourceObjective = "Sammelt Eure Verbündeten in Burg Stromgarde.", completion = "Marran hat ihren Zug gemacht. Der Aufstand hat begonnen.\n\nFaerin und Bräustein haben die Loyalisten von Stromgarde um sich geschart, doch viele stehen auf Marrans Seite.\n\nDas wird ein blutiger Bürgerkrieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[84717] = { id = 84717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg der Roten Dämmerung", description = "Danath und Etrigg sind vorausgeeilt, um Marran zu stellen. Sie hoffen, dass ihr Fall den Aufstand und das Blutvergießen beenden wird.\n\nDoch nach dem, was ich mit eigenen Augen von Joseph dem Erleuchteten gesehen habe...\n\nSo unorthodox er auch sein mag, er bleibt gefährlich. Und ich sage das nur ungern, aber es wäre mir ein Vergnügen, diesen hinterhältigen Schwachkopf endlich umzubringen.\n\nEr versperrt uns den Weg, dort vorn beim Rathaus. Lasst uns ihn ausschalten, und dann Danath und Etrigg beistehen, um diesen Krieg zu beenden.", sourceObjective = "Besiegt Joseph den Erleuchteten und helft Danath and Etrigg.", completion = "Marran wurde verschont.\n\nIch bin mir noch immer nicht sicher, ob sie diese Gnade verdient hat.\n\nDoch ohne Namen und Titel vermag sie nun wenig auszurichten. Nachdem sie zweimal versagt hat, werden die Stromgarder ihr nicht länger folgen. Und ohne die Macht, die ihr ihr Name und Titel einst verlieh, ist sie den Banditen nichts mehr wert.\n\nGnade hin oder her, ich danke dem Licht, dass dieser Konflikt nun beendet ist.\n\nUnd auch Euch danke ich, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84719] = { id = 84719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Expedition wartet", description = "Ich grüße Euch, {name}! Seid Ihr gekommen, um dem Ruf nach Abenteuer auf die Sireneninsel zu folgen?\n\nEin Bergungsteam der Goblins entdeckte eine Insel mit einem seltsamen \"singenden Kristall\" im Zentrum.\n\nWie die Goblins haben auch die Arathi von Heilsturz ein großes Interesse am Kristall gefunden - und wir genauso!\n\nDie meisten Expeditionen sind schon aufgebrochen, aber das letzte Schiff der Goblins legt in Kürze ab.\n\nWenn Ihr Euch beeilt, erwischt Ihr es noch und könnt uns begleiten!", sourceObjective = "Trefft Skaggit am Osttor von Dornogal.", completion = "Ah, Ihr wart das? Ihr habt Aurora davon überzeugt, sich uns anzuschließen, nicht?\n\nNa, dann beeilt Euch mal! Sie haben darauf bestanden, uns von einer anständigen Sturmreitereskorte oder was auch immer aus der Stadt begleiten zu lassen, aber das dauert zu lange!\n\nDie Arathi und anderen Irdenen sind bereits auf der Insel und Ricket fragt sich vermutlich bereits, wo zum Teufel wir bleiben!\n\nKommt schon! Ich kann die Einzelheiten auf dem Weg erzählen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84720] = { id = 84720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Sireneninsel!", description = "Die Sireneninsel ist ein Mysterium. Und womöglich ein profitables.\n\nMeine Besatzung dachte, das große Los gezogen zu haben, als sie eine verlassene Insel mit einem merkwürdigen, singenden Kristall fand...\n\nAber anscheinend ist alles und jeder in Dornogal an bis dato unbeanspruchten \"merkwürdigen, singenden Kristallen\" interessiert. Sowohl die Arathi als auch die Irdenen haben sich schnell ihre Sachen geschnappt und auf den Weg gemacht, bevor wir überhaupt einen Zeppelin buchen konnten!\n\nGlücklicherweise sind Ricket und seine Mannschaft schon vorab los und haben sich dort eingerichtet.\n\nWir sind die Letzten, die aufbrechen, und ich kann's kaum erwarten. Worauf warten wir?", sourceObjective = "Sprecht mit Skaggit, um zur Sireneninsel zu reisen.", completion = "Wir haben es heil geschafft!\n\nLaut Ricket gibts im ganzen Lager kein anderes Thema als diesen Kristall.\n\nIrgendwie scheint jeder eine andere Vorstellung davon zu haben, wie man am besten rausfindet, was man damit anstellen kann.\n\nDer Ansatz von Ricket und mir fand leider kein Gefallen, aber vielleicht seid Ihr etwas diplomatischer.\n\nWollt Ihr vielleicht mitmischen?", sourceObjectiveStatus = "unverified-source-field" }
quests[84721] = { id = 84721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Scannen eines Kristalls", description = "Um den \"singenden Kristall\" im Herzen der Insel zu verstehen, brauchen wir besondere Maschinen.\n\nWir haben ein Gerät gebaut, das die äußeren Facetten scannen soll, doch die Energien des Kristalls sind viel zu komplex für jede Messung. Er hat eine höchst ungewöhnliche Energiesignatur.\n\nDie Goblins und Arathi scheinen erpicht darauf, etwas beizusteuern, also machen wir mit ihrer Hilfe weiter.\n\nNehmt meinen Werkzeugkasten und holt den Prototyp zusammen mit den Komponenten, die die Arathi und Goblins vorbereitet haben.", sourceObjective = "Helft Bargus, indem Ihr den irdenen Prototyp, den Fokus der Arathi und die Energiequelle der Goblins besorgt.", progress = "Normalerweise ist unsere Technologie mehr als imstande, mit Kristallen und den darin befindlichen Energien klarzukommen.\n\nAber die Energien hier sind anomal und scheinen nicht mit unserer Technologie synchron zu sein...", completion = "Skeptizismus... deaktiviert.\n\nAllem Anschein nach harmonieren die strahlenden Überbleibsel aus Heilsturz perfekt mit den Energien, die wir hier vorfinden, sodass wir eine passende Signatur haben, die wir übernehmen können.\n\nDie Batterien der Goblins sind... mehr als großzügig bemessen, aber sie scheinen ihre Arbeit zuverlässig zu machen.\n\nWir sind fast für einen Feldtest bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[84722] = { id = 84722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facettierende Signale", description = "Faszinierend!\n\nDiese strahlenden Überreste von den Arathi scheinen unserem Gerät den nötigen Fokus gegeben zu haben. Jetzt müssen wir sie nur noch auf die Größe einstimmen. \n\nUm das Signal einzustimmen, müssen wir vor Ort Pylonen aufstellen. \n\nNun gilt es, ein paar Tests zu initiieren, {name}. Folgt mir, wenn Ihr mir zur Hand gehen wollt.", sourceObjective = "Trefft Bargus beim Kristall und helft ihm, die Pylone aufzustellen.", progress = "Sobald die Pylonen einsatzbereit sind, sollte ich das Signal per Triangulation lokalisieren können.", completion = "Faszinierend!\n\nDie Einstimmung der Pylonen deutet darauf hin, dass der Kristall weit größer ist, als die Facette erahnen lässt.\n\nNach der Komplexität dieser Signatur scheint er sich kilometerweit unter unseren Füßen zu erstrecken und... Moment, was ist das?\n\nEin zweites Signal entspringt hinter dem Hügel? Äußerst sonderbar...", sourceObjectiveStatus = "unverified-source-field" }
quests[84723] = { id = 84723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Geheimnisse", description = "Diese Ruinen sind... ziemlich alt. Zumindest nach der Vorstellung der meisten Fremdlinge.\n\nWas natürlich die Frage aufwirft: War das Ziel der unfreundlichen Fremdlinge, diese Kammer zu finden, oder hatten sie es auf die Tafel abgesehen?\n\nEinen Hinweis könnten meine Messungen liefern. Die deuten nämlich darauf hin, dass die Energie bloß durch die Tafel hindurch fließt wie durch einen Leiter, aber nicht darin ihren Ursprung hat.\n\nWollen wir uns das näher ansehen?\n\nEine gründliche Untersuchung bringt uns vielleicht Antworten... und zur Quelle der gemessenen Energie.", sourceObjective = "Untersucht die Ruinen und findet den Ursprung des Signals.", completion = "Bei der Schmiede... das ist... \n\n<Bargus starrt den leuchtenden Kristall mit staunend aufgerissenen Augen an und ringt nach Worten. Nach einer Weile nickt er.> \n\nDas muss der Ursprung der zweiten Signatur sein, obwohl die Energien hier mit dem Original verschmolzen zu sein scheinen.\n\nEs ist fast, als wollte er, dass wir diesen Ort finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[84724] = { id = 84724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die strahlende Gruft", description = "Dieses Gewölbe... dieser Kristall... \n\nWer schuf diesen Ort? Wer lebte hier? Und wer ist diese Cyrce, die immer wieder auf den Tafeln erwähnt wird? \n\nAls wir aufbrachen, um mehr über den Kristall zu erfahren, dachte ich nicht, dass wir die Überreste einer antiken Zivilisation weit unter der Erde finden würden. \n\n<Bargus zaust seinen drahtigen Schnurrbart, bevor er Euch ansieht.> \n\nDas bedarf einer genaueren Untersuchung, findet Ihr nicht auch?", sourceObjective = "Untersucht den Kristallschrein.", progress = "Wir scheinen eine gewaltige Entdeckung gemacht zu haben...", completion = "Mehr Fragen und kaum Antworten. \n\nZum Glück konnte das Gerät einige Daten von den Energiemessungen sammeln. \n\nEs wird dauern, das zu verarbeiten, aber bald werden wir diesen \"Sirenenkristall\" besser verstehen. \n\nLasst uns doch bis dahin einen Blick auf diesen Ring und den Citrinsplitter werfen, die Ihr gefunden habt. Angorla hier kann helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84725] = { id = 84725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reif ruft", description = "<Angorla blickt Euch über ihre Brille hinweg aufgeregt an.>\n\nKönnt Ihr das hören, {name}?\n\nDieser kleine, bescheidene Citrin ruft nach dem Ring. Genau, wie der Sirenenkristall nach Euch und uns allen gerufen hat.\n\nIch bin nicht sicher, was passiert, wenn Ihr sie vereint... aber es gibt nur einen Weg, das herauszufinden.\n\nLegt Euch den Ring an und steckt den Citrin in die Fassung.", sourceObjective = "Legt Cyrces Reif an und setzt den runenverzierten Citrin des Windsängers in den Platz des singenden Windes ein.\n\nDann holt den runenverzierten Citrin des Windsängers wieder heraus.", progress = "Habt Ihr den Citrin in den Reif gefasst, {name}?", completion = "Ich kann es bis hierher spüren... das Strahlen. Es pulsiert vor lange schlummernder Macht.\n\nWer hat diese kleinen Citrine geschliffen? Warum scheinen sie perfekt in den Ring zu passen? Dabei wurden sie doch getrennt aufgefunden.\n\nOh, ich wünschte, ich hätte gesehen, was Ihr und Bargus im Gewölbe gefunden habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[84726] = { id = 84726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgedeckte Geheimnisse", description = "<Angorla nimmt Eure Hand und begutachtet den kristallbesetzten Ring im Detail.> \n\nSpürt Ihr die Energie, die in ihm summt, {name}? Der Ring fühlt sich... erwacht an. \n\nAuf der Insel sind möglicherweise noch mehr Geheimnisse verborgen, die nur darauf warten, dass Ihr sie aufdeckt.\n\nAurora hat uns ermutigt, diese Insel zu erkunden und zu erforschen, aber ich werde hier gebraucht. \n\nWarum geht Ihr nicht und seht, welche anderen Geheimnisse sie birgt?", sourceObjective = "Deckt verborgene Geheimnisse auf der Sireneninsel auf.", progress = "Was habt Ihr gefunden? Noch einen Schatz vielleicht?", completion = "Seltsam. Sogar als Fragmente summen die Teile vor Energie. Ich frage mich, ob... \n\n<Angorla presst die Fragmente wie Puzzlestücke aneinander und drückt sie mit den Händen zusammen. Einen Moment später streckt sie die Hand zu Euch aus und offenbart einen sorgfältig zusammengesetzten Splitter.> \n\nEr ist vielleicht nicht so filigran geschliffen und kunstvoll wie die Citrine, die Ihr im Gewölbe gefunden habt, aber sogar in einem kleinen Stein wie diesem steckt Energie.", sourceObjectiveStatus = "unverified-source-field" }
quests[84727] = { id = 84727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zweite Signal", description = "Eine unerwartete Entwicklung.\n\nDie Energiesignatur scheint eine zweite Quelle zu haben, und die liegt direkt nördlich von hier.\n\nNeugierde aktiviert.\n\nNach der geschätzten Größe des Kristalls zu urteilen, vermute ich, dass es sich um eine zweite freiliegende Facette handeln könnte.\n\nWeitere Untersuchungen sind erforderlich. Folgt mir.", sourceObjective = "Folgt Bargus nach Norden.", completion = "Wir sind wohl doch nicht die Einzigen auf dieser Insel, {name}. \n\n \n\nMit Gewalt zu handeln, bevor diplomatische Gespräche geführt wurden... eine unlogische Provokation, die unvorteilhaften Konsequenzen nach sich zog.", sourceObjectiveStatus = "unverified-source-field" }
quests[84728] = { id = 84728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neugeschmiedet", description = "Der gesprungene Citrin, den Ihr gefunden habt, scheint perfekt in die Sockel auf dem Ring zu passen, und doch... \n\n<Als Angorla den Splitter in den Ring einsetzt, wackelt der Citrin und springt heraus.> \n\nDer Ring scheint das Stück abzustoßen. Vielleicht wird der Ring ihn annehmen, wenn wir den Citrin reparieren und die Energie im Splitter stabilisieren können? \n\nDa Ihr Bargus so sehr geholfen habt, würdet Ihr mir zur Hand gehen?", sourceObjective = "Helft Angorla, den Citrin zu reparieren.", completion = "<Angorla hält den leuchtenden Citrin in der Hand, bevor sie ihn Euch hinhält.> \n\n Das scheint funktioniert zu haben... Ich habe noch nie derartige Energie von einem so kleinen Kristall ausgehen gespürt. \n\nDie darauf eingravierten Runen sind ziemlich alt und enorm mächtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[84730] = { id = 84730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gepanzerte Pflicht", description = "Das anorganische Material auf dieser Insel ist äußerst faszinierend. Durch die von Salzwasser und Stürmen verursachte Erosion wurden die Minerale hier angereichert.\n\nUnd angereicherte Minerale sind genau das, was ein Weihekandidat braucht, um daraus neue Waffen herzustellen.\n\nBringt mir genügend sturmgesprenkelte Trümmer von den unzähligen Kreaturen der Insel. Ich würde gerne sehen, ob sie für mein Handwerk geeignet sind.", sourceObjective = "Sammelt 50 sturmgesprenkelte Trümmer.\n\nIhr könnt sie von Kreaturen auf der Sireneninsel erbeuten.", progress = "Habt Ihr sturmgesprenkelte Trümmer gefunden? Es sollte hier reichlich geben, wenn Ihr bereit seid zu suchen.", completion = "<Bargus zertrümmert einen Brocken in seiner Hand und verteilt die Fragmente über seinen ganzen Amboss, um sie zu untersuchen.>\n\nFaszinierend... In den Brocken sind Splitter von kristallinem Material enthalten. Sind das vielleicht erodierte Fragmente des Sirenenkristalls?\n\nIch glaube, ich hätte da einen weiteren Auftrag für Euch, {name}.\n\nAber bedient Euch zuerst einmal an den Waffen, die ich geschmiedet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[84731] = { id = 84731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbrotkrumen" }
quests[84735] = { id = 84735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit der Dunkeleisenzwerge", description = "Es kennen nur wenige die Wahrheit hinter dem Dunkeleisenklan. Und noch weniger haben ihn mit eigenen Augen gesehen.\n\nDie Zeitwanderer haben zugestimmt, uns zurückzubringen. Sie bringen uns zu der Zeit, als unser Klan seinen Imperator verlor. Und dadurch kann ich Euch hoffentlich alles zeigen, was sich aus dieser Niederlage ergeben hat. Das Gute. Und das Schlechte...\n\nWerdet Ihr die Wahrheit mit eigenen Augen bezeugen?", sourceObjective = "Besiegt Imperator Dagran Thaurissan im Schlachtzug \"Rückkehr in die Schwarzfelstiefen\".", progress = "Ich werde Euch auf Eurem Weg führen. Doch das Ende dieses Weges... Ich weiß nicht, ob ich es ertragen kann, das erneut zu durchleben.", completion = "Der Dunkeleisenklan war an Ragnaros verloren. Ich träumte davon, ihn aus seinem Bann zu befreien. Hätte ich das doch nur gekonnt, bevor mein Gatte...\n\nHier. Nehmt diese Marken von unseren Gastgebern. Und danke, dass Ihr die Wahrheit mit eigenen Augen bezeugt habt.", sourceObjectiveStatus = "unverified-source-field" }
